def _read_pat(pat_file: str) -> str:
    """Read the FIRSTINSTANCE machine-user PAT from the shared volume file.

    Args:
        pat_file: Filesystem path to the PAT file the Zitadel server wrote during
            FIRSTINSTANCE setup (``ZITADEL_FIRSTINSTANCE_PATPATH``).

    Returns:
        The Personal Access Token string.

    Raises:
        SystemExit(1): When the file is missing or empty.
    """
    if not os.path.exists(pat_file):
        logger.error(
            "PAT file not found at '%s'. "
            "Fix: verify the Zitadel server's ZITADEL_FIRSTINSTANCE_PATPATH writes "
            "to this path and the init-job mounts the shared machinekey volume. "
            "Note: FIRSTINSTANCE only runs on a fresh instance — an existing "
            "deployment needs a zitadel-db-data volume reset to regenerate the PAT.",
            pat_file,
        )
        sys.exit(1)
    with open(pat_file, "r", encoding="utf-8") as fh:
        token = fh.read().strip()
    if not token:
        logger.error(
            "PAT file '%s' is empty. "
            "Fix: verify FIRSTINSTANCE setup completed and wrote the machine-user "
            "PAT before the server became healthy.",
            pat_file,
        )
        sys.exit(1)
    logger.info("pat_loaded path=%s", pat_file)
    return token


# ---------------------------------------------------------------------------
# HTTP helpers (stdlib only — no external dependencies)
# ---------------------------------------------------------------------------

#: Per-socket-operation deadline for every Management API call. Without it,
#: urllib inherits the process-wide default socket timeout of ``None``: a
#: Zitadel instance that accepts the connection and then stops responding
#: would block this init container forever — no output, no exit code, and the
#: whole compose stack waiting on a service_completed_successfully dependency
#: that never completes. The deadline is re-armed per read, so a slow but
#: progressing response is never cut off.
_REQUEST_TIMEOUT_SECONDS: float = 30.0

#: How long the applier waits for the Management API to serve before its first
#: call. The server's healthcheck (``zitadel ready``) passes as soon as the HTTP
#: listener is up, but for a few seconds after that the REST gateway still
#: answers 503 (gRPC UNAVAILABLE: its in-process dial to the API is refused), so
#: an applier started on ``service_healthy`` must not treat that window as a
#: provisioning failure.
_API_READY_TIMEOUT_SECONDS: float = 120.0

#: Pause between readiness probes.
_API_READY_POLL_SECONDS: float = 2.0

#: Statuses the gateway returns while the API behind it is still starting.
_API_STARTING_STATUSES: frozenset[int] = frozenset({502, 503, 504})


def _management_request(
    url: str,
    api: _Api,
    *,
    method: str = "GET",
    payload: dict[str, Any] | None = None,
) -> urllib.request.Request:
    """Build a Management API request carrying the Bearer PAT and the instance ``Host`` header."""
    data: bytes | None = None
    headers: dict[str, str] = {
        "Accept": "application/json",
        "Authorization": "Bearer %s" % api.token,
    }
    if api.org_id is not None:
        headers[_ORG_CONTEXT_HEADER] = api.org_id
    if payload is not None:
        headers["Content-Type"] = "application/json"
        data = json.dumps(payload).encode("utf-8")

    req = urllib.request.Request(url, data=data, headers=headers, method=method)
    # Override the Host header (urllib would otherwise derive it from the URL's
    # internal service name, which does not match any Zitadel v3 instance).
    req.add_unredirected_header("Host", api.host_header)
    return req


def _management_api_not_ready(api: _Api) -> str | None:
    """Probe the Management API once: ``None`` when it serves, else why it does not yet.

    Any answer other than a gateway-starting status comes from the API itself
    (including 401/403, which the provisioning calls report with their own fix),
    so it counts as ready.
    """
    req = _management_request(api.mgmt_base + "/orgs/me", api)
    try:
        # The base URL was checked by _require_http_base_url, so urlopen can only open http(s).
        with urllib.request.urlopen(req, timeout=_REQUEST_TIMEOUT_SECONDS):  # nosec B310
            return None
    except urllib.error.HTTPError as exc:
        if exc.code in _API_STARTING_STATUSES:
            return "HTTP %d" % exc.code
        return None
    except OSError as exc:
        # URLError (refused, unresolvable), TimeoutError and a dropped connection
        # are all OSErrors: the server is not accepting requests yet.
        return str(getattr(exc, "reason", exc))


def _wait_for_management_api(
    api: _Api,
    *,
    timeout_seconds: float = _API_READY_TIMEOUT_SECONDS,
    poll_seconds: float = _API_READY_POLL_SECONDS,
) -> None:
    """Block until the Management API serves, exiting non-zero after *timeout_seconds*.

    Raises:
        SystemExit(1): The API did not serve within the deadline.
    """
    deadline = time.monotonic() + timeout_seconds
    attempt = 0
    while True:
        attempt += 1
        reason = _management_api_not_ready(api)
        if reason is None:
            if attempt > 1:
                logger.info("zitadel_api_ready attempts=%d", attempt)
            return
        if time.monotonic() >= deadline:
            logger.error(
                "The Zitadel Management API at '%s' was still not serving after %ss "
                "(last answer: %s). Fix: check the Zitadel server logs; it passed its "
                "healthcheck but its API never came up.",
                api.mgmt_base,
                timeout_seconds,
                reason,
            )
            sys.exit(1)
        logger.info("zitadel_api_waiting attempt=%d reason=%s", attempt, reason)
        time.sleep(poll_seconds)


def _json_request(
    url: str,
    api: _Api,
    *,
    method: str = "GET",
    payload: dict[str, Any] | None = None,
) -> tuple[int, dict[str, Any]]:
    """Execute a JSON Management API request and return ``(status_code, body)``.

    Attaches the Bearer PAT and the instance ``Host`` header (so Zitadel v3 routes
    the request to the matching instance even though the URL targets the internal
    service name).

    Args:
        url: Full request URL.
        api: Connection context (base URL, token, host header).
        method: HTTP method (GET, POST, PUT, PATCH, etc.).
        payload: Dict to serialize as JSON request body. ``None`` for no body.

    Returns:
        ``(status_code, parsed_json_body)``.  When the response body is not valid
        JSON, returns an empty dict as the body.

    Raises:
        SystemExit(1): On network-level errors, logged with details.
    """
    req = _management_request(url, api, method=method, payload=payload)
    try:
        # Every URL here derives from the base URL apply_provisioning checked with
        # _require_http_base_url, so urlopen can only open http(s).
        with urllib.request.urlopen(req, timeout=_REQUEST_TIMEOUT_SECONDS) as resp:  # nosec B310
            raw = resp.read()
            status = resp.status
    except urllib.error.HTTPError as exc:
        raw = exc.read()
        status = exc.code
    except (urllib.error.URLError, TimeoutError) as exc:
        # A read that times out surfaces as a bare TimeoutError, not a URLError
        # (only connect-phase timeouts are wrapped), so both must land on this
        # same actionable message rather than an unhandled traceback.
        reason = (
            exc.reason
            if isinstance(exc, urllib.error.URLError)
            else "no response within %ss" % _REQUEST_TIMEOUT_SECONDS
        )
        logger.error(
            "Network error calling '%s %s': %s. "
            "Fix: verify ZITADEL_INSTANCE_URL is reachable from the init container "
            "and that the server healthcheck passed before this job started.",
            method,
            url,
            reason,
        )
        sys.exit(1)

    try:
        body: dict[str, Any] = json.loads(raw.decode("utf-8")) if raw else {}
    except json.JSONDecodeError:
        body = {}

    return status, body


#: The i18n keys of Zitadel's no-op-update rejection, as it returns them when it
#: does not translate the key: the generic ``Errors.NoChangesFound`` and the
#: per-aggregate ``Errors.<Aggregate>[.<Resource>].NotChanged`` (the org login
#: policy update answers ``Errors.Org.LoginPolicy.NotChanged (Org-5M9vdd)``).
_NO_CHANGES_KEY = re.compile(
    r"\bErrors\.(?:NoChangesFound|(?:\w+\.)+NotChanged)\b", re.IGNORECASE
)
#: The translated texts of the same keys: ``Errors.NoChangesFound`` reads ``"No changes"``
#: (Zitadel cases it either way), and a per-aggregate ``NotChanged`` reads ``"<Resource>
#: has not been changed"`` (the instance domain policy answers ``"Org IAM Policy has not
#: been changed (INSTANCE-pl9fN)"``).
_NO_CHANGES_TEXT = re.compile(r"\bno changes\b|\bhas not been changed\b", re.IGNORECASE)


def _error_texts(body: dict[str, Any]) -> list[str]:
    """The top-level ``message`` and every ``details[].message`` of a Zitadel error."""
    texts = [body.get("message")]
    details = body.get("details")
    if isinstance(details, list):
        texts.extend(d.get("message") for d in details if isinstance(d, dict))
    return [text for text in texts if isinstance(text, str)]


def _is_no_changes(status: int, body: dict[str, Any]) -> bool:
    """Return ``True`` for Zitadel's HTTP 400 no-op-update response.

    An idempotent re-run reissues update PUTs whose payload equals what Zitadel
    already stores. Zitadel rejects such no-op updates with HTTP 400, code 9. For
    a converged deployment that is the expected steady state, not a failure, so
    update callers treat it as success (the desired state is already applied).

    Zitadel words the rejection two ways, and both are recognised (in the top-level
    ``message`` and in each ``details[].message``):

    - translated, as the texts in :data:`_NO_CHANGES_TEXT`: ``"No changes
      (COMMAND-...)"`` and ``"<Resource> has not been changed (...)"``. Zitadel is
      inconsistent about casing -- the flow-trigger SET returns ``"No Changes
      (COMMAND-Nfh52)"`` while update PUTs return ``"No changes (...)"`` -- so the
      match ignores case;
    - untranslated, as the i18n key in :data:`_NO_CHANGES_KEY`.

    Args:
        status: HTTP status code from the update call.
        body: Parsed JSON response body.

    Returns:
        ``True`` when the response is a Zitadel no-op-update rejection.
    """
    if status != 400:
        return False
    return any(
        _NO_CHANGES_TEXT.search(text) or _NO_CHANGES_KEY.search(text)
        for text in _error_texts(body)
    )


