def _list_projects(api: _Api) -> list[dict[str, Any]]:
    """Fetch all existing Zitadel projects.

    Zitadel exposes project listing only via the search endpoint
    (``POST /management/v1/projects/_search``); a plain ``GET /projects`` returns
    HTTP 405 (Method Not Allowed). This mirrors every other list call in this
    file (roles/apps/idps all use ``_search``).
    """
    url = api.mgmt_base + "/projects/_search"
    status, body = _json_request(url, api, method="POST", payload={})
    if status not in (200, 404):
        logger.error(
            "Failed to list projects (HTTP %d): %s. "
            "Fix: verify the machine-user PAT has IAM_OWNER permissions.",
            status,
            body,
        )
        sys.exit(1)
    result = body.get("result")
    if isinstance(result, list):
        return result
    return []


def _find_project_by_name(
    projects: list[dict[str, Any]], name: str
) -> dict[str, Any] | None:
    """Return the first project entry whose ``name`` matches, or ``None``."""
    for p in projects:
        if p.get("name") == name:
            return p
    return None


def _create_project(
    api: _Api, name: str, role_assertion: bool, has_project_check: bool
) -> str:
    """Create a Zitadel project with *name* and return its project ID.

    Args:
        api: Connection context.
        name: Project name.
        role_assertion: Value for ``projectRoleAssertion`` ("Assert Roles on
            Authentication").  Zitadel only mints the
            ``urn:zitadel:iam:org:project:roles`` claim into tokens when this is
            true, so a project with roles must enable it or every role-guarded
            route 403s.  Defaults to ``false`` on create when omitted, so it is
            sent explicitly.
        has_project_check: Value for ``hasProjectCheck`` ("Check for Project on
            Authentication"): only users of the project's own organization (or an
            organization the project is granted to) may sign in to its apps.

    Returns:
        The new project's ``id`` string.

    Raises:
        SystemExit(1): On API error.
    """
    url = api.mgmt_base + "/projects"
    payload: dict[str, Any] = {
        "name": name,
        "projectRoleAssertion": role_assertion,
        "hasProjectCheck": has_project_check,
    }
    status, body = _json_request(url, api, method="POST", payload=payload)
    if status not in (200, 201):
        logger.error(
            "Failed to create project '%s' (HTTP %d): %s.",
            name,
            status,
            body,
        )
        sys.exit(1)
    project_id = body.get("id")
    if not isinstance(project_id, str) or not project_id:
        logger.error(
            "Create project '%s' response missing 'id'. Got: %s.",
            name,
            body,
        )
        sys.exit(1)
    logger.info("project_created name=%s id=%s", name, project_id)
    return project_id


def _update_project(
    api: _Api,
    project_id: str,
    name: str,
    role_assertion: bool,
    has_project_check: bool,
) -> None:
    """Update the project name, role assertion and project check (PUT /projects/{id}).

    A full-replace project PUT that omits ``projectRoleAssertion`` resets it to
    ``false``, which drops the project-roles claim and 403s every role-guarded
    route — so it is re-asserted on every update, and ``hasProjectCheck`` with it
    (an omitted check resets to ``false`` and would let any instance user sign in to
    the project).  An existing project created before these flags were emitted (or by
    an older applier) is converged here.

    Args:
        api: Connection context.
        project_id: Zitadel project ID.
        name: New project name.
        role_assertion: Value for ``projectRoleAssertion`` ("Assert Roles on
            Authentication").
        has_project_check: Value for ``hasProjectCheck``.

    Raises:
        SystemExit(1): On API error.
    """
    url = "%s/projects/%s" % (api.mgmt_base, project_id)
    payload: dict[str, Any] = {
        "name": name,
        "projectRoleAssertion": role_assertion,
        "hasProjectCheck": has_project_check,
    }
    status, body = _json_request(url, api, method="PUT", payload=payload)
    if status not in (200, 201) and not _is_no_changes(status, body):
        logger.error(
            "Failed to update project id=%s name=%s (HTTP %d): %s.",
            project_id,
            name,
            status,
            body,
        )
        sys.exit(1)
    logger.info("project_updated id=%s name=%s", project_id, name)


def _ensure_project(
    api: _Api, name: str, role_assertion: bool, has_project_check: bool = False
) -> str:
    """Idempotently get-or-create a Zitadel project and converge its role assertion.

    Fetches the project list first; creates the project when absent.  When the
    project already exists it is PUT-updated so ``projectRoleAssertion`` converges
    to the desired value (the create-time flag never reaches a project that was
    created before this fix), mirroring how roles and OIDC apps are reconciled.
    Zitadel's "No changes" 400 on a converged re-run is treated as success.

    Args:
        api: Connection context.
        name: Desired project name.
        role_assertion: Desired ``projectRoleAssertion`` value for the project.
        has_project_check: Desired ``hasProjectCheck`` value for the project.

    Returns:
        The project ID (existing or newly created).
    """
    existing = _list_projects(api)
    match = _find_project_by_name(existing, name)
    if match is not None:
        project_id = match.get("id")
        if not isinstance(project_id, str) or not project_id:
            logger.error(
                "Existing project '%s' has no id. Got: %s.",
                name,
                match,
            )
            sys.exit(1)
        logger.info("project_exists name=%s id=%s", name, project_id)
        _update_project(api, project_id, name, role_assertion, has_project_check)
        return project_id
    return _create_project(api, name, role_assertion, has_project_check)


# ---------------------------------------------------------------------------
# Organization provisioning
# ---------------------------------------------------------------------------


def _find_org_id(api: _Api, name: str) -> str | None:
    """Return the id of the organization named exactly *name*, or ``None``.

    Searches through the Admin API (``POST /admin/v1/orgs/_search``): the Management API
    lists only the caller's own organization.

    Raises:
        SystemExit(1): On a non-200/404 API error.
    """
    payload: dict[str, object] = {
        "queries": [
            {"nameQuery": {"name": name, "method": "TEXT_QUERY_METHOD_EQUALS"}}
        ]
    }
    status, body = _json_request(
        _admin_url(api, "/orgs/_search"), api, method="POST", payload=payload
    )
    if status not in (200, 404):
        logger.error(
            "Failed to search organizations for '%s' (HTTP %d): %s. "
            "Fix: verify the machine-user PAT has IAM_OWNER permissions.",
            name,
            status,
            body,
        )
        sys.exit(1)
    result = body.get("result")
    if isinstance(result, list):
        for org in result:
            if isinstance(org, dict) and org.get("name") == name:
                org_id = org.get("id")
                if isinstance(org_id, str) and org_id:
                    return org_id
    return None


def _create_org(api: _Api, name: str) -> str:
    """Create the organization *name* (``POST /management/v1/orgs``) and return its id.

    Raises:
        SystemExit(1): On API error or a response without an ``id``.
    """
    status, body = _json_request(
        api.mgmt_base + "/orgs", api, method="POST", payload={"name": name}
    )
    org_id = body.get("id")
    if status not in (200, 201) or not isinstance(org_id, str) or not org_id:
        logger.error(
            "Failed to create organization '%s' (HTTP %d): %s. "
            "Fix: verify the machine-user PAT has IAM_OWNER permissions (org.create).",
            name,
            status,
            body,
        )
        sys.exit(1)
    logger.info("organization_created name=%s id=%s", name, org_id)
    return org_id


def _ensure_organization(api: _Api, organization: Mapping[str, object]) -> str:
    """Idempotently get-or-create the organization an artifact project declares.

    Args:
        api: Connection context acting in the default organization.
        organization: The project's ``organization`` block; its ``name`` is the
            organization's name.

    Returns:
        The organization id.

    Raises:
        SystemExit(1): The block carries no ``name``, or an API call fails.
    """
    name = organization.get("name")
    if not isinstance(name, str) or not name:
        logger.error(
            "Project 'organization' block is missing its 'name'. Got: %s. "
            "Fix: regenerate the provisioning artifact.",
            organization,
        )
        sys.exit(1)
    existing = _find_org_id(api, name)
    if existing is not None:
        logger.info("organization_exists name=%s id=%s", name, existing)
        return existing
    return _create_org(api, name)


# ---------------------------------------------------------------------------
# Token-introspection client (second-factor proof)
# ---------------------------------------------------------------------------

#: A project's introspection client is an API application that signs an assertion with a
#: private key (RFC 7523), so no reusable shared secret is ever written or sent.
_API_AUTH_METHOD_PRIVATE_KEY_JWT: str = "API_AUTH_METHOD_TYPE_PRIVATE_KEY_JWT"
_APP_KEY_TYPE_JSON: str = "KEY_TYPE_JSON"

#: The members of the key details Zitadel returns that a service needs to sign an assertion.
_APP_KEY_DETAIL_FIELDS: tuple[str, ...] = ("keyId", "key", "clientId")


def _find_api_app(api: _Api, project_id: str, name: str) -> tuple[str, str] | None:
    """Return ``(appId, clientId)`` of the API application *name*, or ``None``."""
    for app in _list_apps(api, project_id):
        if app.get("name") != name:
            continue
        api_config = app.get("apiConfig")
        app_id = app.get("id")
        client_id = api_config.get("clientId") if isinstance(api_config, dict) else None
        if isinstance(app_id, str) and app_id and isinstance(client_id, str) and client_id:
            return app_id, client_id
    return None


def _ensure_api_app(api: _Api, project_id: str, name: str) -> str:
    """Idempotently get-or-create the key-authenticated API application *name*.

    An existing application is converged to the private-key method too, so one created
    by hand with a shared secret does not keep authenticating introspection that way.

    Returns:
        The application id.

    Raises:
        SystemExit(1): On API error or a response without the identifiers.
    """
    existing = _find_api_app(api, project_id, name)
    if existing is not None:
        app_id = existing[0]
        status, body = _json_request(
            "%s/projects/%s/apps/%s/api_config" % (api.mgmt_base, project_id, app_id),
            api,
            method="PUT",
            payload={"authMethodType": _API_AUTH_METHOD_PRIVATE_KEY_JWT},
        )
        if status not in (200, 201) and not _is_no_changes(status, body):
            logger.error(
                "Failed to set API app '%s' to private-key authentication (HTTP %d): %s.",
                name,
                status,
                body,
            )
            sys.exit(1)
        logger.info("api_app_exists name=%s appId=%s", name, app_id)
        return app_id
    status, body = _json_request(
        "%s/projects/%s/apps/api" % (api.mgmt_base, project_id),
        api,
        method="POST",
        payload={"name": name, "authMethodType": _API_AUTH_METHOD_PRIVATE_KEY_JWT},
    )
    created_id = body.get("appId")
    if status not in (200, 201) or not isinstance(created_id, str) or not created_id:
        logger.error(
            "Failed to create API app '%s' (HTTP %d): %s.", name, status, body
        )
        sys.exit(1)
    logger.info("api_app_created name=%s appId=%s", name, created_id)
    return created_id


def _list_app_key_ids(api: _Api, project_id: str, app_id: str) -> list[str]:
    """The ids of every key the application holds."""
    status, body = _json_request(
        "%s/projects/%s/apps/%s/keys/_search" % (api.mgmt_base, project_id, app_id),
        api,
        method="POST",
        payload={},
    )
    if status not in (200, 404):
        logger.error(
            "Failed to list keys of app id=%s (HTTP %d): %s.", app_id, status, body
        )
        sys.exit(1)
    result = body.get("result")
    if not isinstance(result, list):
        return []
    return [
        key["id"]
        for key in result
        if isinstance(key, dict) and isinstance(key.get("id"), str) and key["id"]
    ]


def _decode_key_details(raw_details: object) -> dict[str, str] | None:
    """The key details' members a service signs with, or ``None`` when they are not all there."""
    if not isinstance(raw_details, str):
        return None
    try:
        details = json.loads(base64.b64decode(raw_details).decode("utf-8"))
    except (ValueError, UnicodeDecodeError):
        return None
    if not isinstance(details, dict):
        return None
    wanted = {name: details.get(name) for name in _APP_KEY_DETAIL_FIELDS}
    if not all(isinstance(value, str) and value for value in wanted.values()):
        return None
    return {name: str(value) for name, value in wanted.items()}


def _add_app_key(api: _Api, project_id: str, app_id: str) -> tuple[str, dict[str, str]]:
    """Generate a JSON key for the application; return ``(id, signing members)``.

    The private half is returned by Zitadel exactly once, in ``keyDetails``.

    Raises:
        SystemExit(1): On API error or key details that do not hold the key.
    """
    status, body = _json_request(
        "%s/projects/%s/apps/%s/keys" % (api.mgmt_base, project_id, app_id),
        api,
        method="POST",
        payload={"type": _APP_KEY_TYPE_JSON},
    )
    key_id = body.get("id")
    details = _decode_key_details(body.get("keyDetails")) if status in (200, 201) else None
    if not isinstance(key_id, str) or not key_id or details is None:
        logger.error(
            "Failed to generate a key for app id=%s (HTTP %d): the response carries no "
            "usable keyDetails (keys: %s).",
            app_id,
            status,
            sorted(body.keys()),
        )
        sys.exit(1)
    return key_id, details


def _delete_app_key(api: _Api, project_id: str, app_id: str, key_id: str) -> None:
    """Remove one key of the application; a key already gone is converged."""
    status, body = _json_request(
        "%s/projects/%s/apps/%s/keys/%s" % (api.mgmt_base, project_id, app_id, key_id),
        api,
        method="DELETE",
    )
    if status not in (200, 204, 404):
        logger.error(
            "Failed to delete key id=%s of app id=%s (HTTP %d): %s.",
            key_id,
            app_id,
            status,
            body,
        )
        sys.exit(1)


def _provision_introspection_client(
    api: _Api, project_id: str, spec: Mapping[str, object]
) -> None:
    """Provision the API application services introspect tokens with, and its key file.

    Creates the key-authenticated API application, adds a fresh key, writes the key
    (``keyId``, ``key``, ``clientId``) to the spec's ``credentialFile`` on the volume the
    services mount read-only, then deletes every earlier key, so a key leaked from an
    earlier run stops authenticating and the file always holds the one valid key. The key
    is added before the old ones go, so no run leaves the file without a valid key.

    Args:
        api: Connection context acting in the project's organization.
        project_id: The project the application belongs to; its id is in the ``aud`` of
            every token the project's apps mint, which introspection requires.
        spec: The project's ``introspectionClient`` block: ``name`` and ``credentialFile``.

    Raises:
        SystemExit(1): The block is malformed, or an API call fails.
    """
    name = spec.get("name")
    credential_file = spec.get("credentialFile")
    if (
        not isinstance(name, str)
        or not name
        or not isinstance(credential_file, str)
        or not credential_file
    ):
        logger.error(
            "Project 'introspectionClient' block needs 'name' and 'credentialFile'. "
            "Got: %s. Fix: regenerate the provisioning artifact.",
            spec,
        )
        sys.exit(1)
    app_id = _ensure_api_app(api, project_id, name)
    earlier = _list_app_key_ids(api, project_id, app_id)
    new_key_id, signing = _add_app_key(api, project_id, app_id)
    _write_machine_credentials(credential_file, signing)
    for key_id in earlier:
        if key_id != new_key_id:
            _delete_app_key(api, project_id, app_id, key_id)
    logger.info("introspection_client_ready name=%s keys_replaced=%d", name, len(earlier))


# ---------------------------------------------------------------------------
# Role provisioning
# ---------------------------------------------------------------------------


def _list_roles(api: _Api, project_id: str) -> list[dict[str, Any]]:
    """Fetch all existing roles for *project_id*."""
    url = "%s/projects/%s/roles/_search" % (api.mgmt_base, project_id)
    status, body = _json_request(url, api, method="POST", payload={})
    if status not in (200, 404):
        logger.error(
            "Failed to list roles for project id=%s (HTTP %d): %s.",
            project_id,
            status,
            body,
        )
        sys.exit(1)
    result = body.get("result")
    if isinstance(result, list):
        return result
    return []


def _create_role(
    api: _Api,
    project_id: str,
    key: str,
    display_name: str,
    description: str,
) -> None:
    """Create a project role (POST /projects/{id}/roles).

    Raises:
        SystemExit(1): On API error.
    """
    url = "%s/projects/%s/roles" % (api.mgmt_base, project_id)
    payload: dict[str, str] = {
        "roleKey": key,
        "displayName": display_name,
        "description": description,
    }
    status, body = _json_request(url, api, method="POST", payload=payload)
    if status not in (200, 201):
        logger.error(
            "Failed to create role key=%s project=%s (HTTP %d): %s.",
            key,
            project_id,
            status,
            body,
        )
        sys.exit(1)
    logger.info("role_created project=%s key=%s", project_id, key)


def _update_role(
    api: _Api,
    project_id: str,
    key: str,
    display_name: str,
    description: str,
) -> None:
    """Update a project role (PUT /projects/{id}/roles/{key}).

    Raises:
        SystemExit(1): On API error.
    """
    url = "%s/projects/%s/roles/%s" % (api.mgmt_base, project_id, key)
    payload: dict[str, str] = {
        "displayName": display_name,
        "description": description,
    }
    status, body = _json_request(url, api, method="PUT", payload=payload)
    if status not in (200, 201) and not _is_no_changes(status, body):
        logger.error(
            "Failed to update role key=%s project=%s (HTTP %d): %s.",
            key,
            project_id,
            status,
            body,
        )
        sys.exit(1)
    logger.info("role_updated project=%s key=%s", project_id, key)


def _ensure_roles(
    api: _Api,
    project_id: str,
    roles: list[dict[str, Any]],
) -> None:
    """Idempotently create or update all roles for a project.

    Args:
        api: Connection context.
        project_id: Zitadel project ID.
        roles: List of ``{"key": str, "displayName": str, "description": str}`` dicts.

    Raises:
        SystemExit(1): When a role entry is missing required fields.
    """
    existing = _list_roles(api, project_id)
    existing_keys: set[str] = {r.get("key", "") for r in existing}

    for role in roles:
        key = role.get("key")
        display_name = role.get("displayName")
        description = role.get("description", "")
        if not isinstance(key, str) or not key:
            logger.error(
                "Role entry in artifact is missing required 'key' field. "
                "Got: %s. Fix: regenerate the provisioning artifact.",
                role,
            )
            sys.exit(1)
        if not isinstance(display_name, str):
            display_name = key
        if not isinstance(description, str):
            description = ""

        if key in existing_keys:
            _update_role(api, project_id, key, display_name, description)
        else:
            _create_role(api, project_id, key, display_name, description)


# ---------------------------------------------------------------------------
# OIDC application provisioning
# ---------------------------------------------------------------------------


def _list_apps(api: _Api, project_id: str) -> list[dict[str, Any]]:
    """Fetch all existing apps for *project_id*."""
    url = "%s/projects/%s/apps/_search" % (api.mgmt_base, project_id)
    status, body = _json_request(url, api, method="POST", payload={})
    if status not in (200, 404):
        logger.error(
            "Failed to list apps for project id=%s (HTTP %d): %s.",
            project_id,
            status,
            body,
        )
        sys.exit(1)
    result = body.get("result")
    if isinstance(result, list):
        return result
    return []


#: OIDC-config fields that a full-replace ``oidc_config`` PUT resets to their
#: defaults when omitted: ``devMode`` (omitting it resets to ``false``, which
#: makes Zitadel reject ``http://localhost`` redirect URIs), ``accessTokenType``
#: (resets to opaque, which the JWKS-validating backend cannot verify),
#: ``loginVersion`` (the per-app custom-login base URI), the role-assertion
#: flags ``accessTokenRoleAssertion`` / ``idTokenRoleAssertion`` (each resets to
#: ``false``, which drops the project-roles claim and 403s every role-guarded
#: route), and ``postLogoutRedirectUris`` (resets to none, after which Zitadel
#: ignores the app's post-logout redirect and strands the user on its own
#: logged-out page).  Both create and update payloads must carry these so a
#: redeploy never strips them.
_OIDC_PRESERVED_FIELDS: tuple[str, ...] = (
    "devMode",
    "accessTokenType",
    "loginVersion",
    "accessTokenRoleAssertion",
    "idTokenRoleAssertion",
    "postLogoutRedirectUris",
)


def _oidc_preserved_fields(app: dict[str, Any]) -> dict[str, Any]:
    """Return the subset of *app* fields that must survive a full-replace PUT.

    Only keys actually present in the artifact are returned, so the applier
    never sends a field the generator did not emit.
    """
    return {key: app[key] for key in _OIDC_PRESERVED_FIELDS if key in app}


def _create_oidc_app(
    api: _Api,
    project_id: str,
    app: dict[str, Any],
) -> str:
    """Create an OIDC application under *project_id* and return its ``appId``.

    Args:
        api: Connection context.
        project_id: Zitadel project ID.
        app: OIDC app dict from the artifact.

    Returns:
        The new app's ``appId`` string.

    Raises:
        SystemExit(1): On missing fields or API error.
    """
    name = app.get("name")
    redirect_uris = app.get("redirectUris", [])
    response_types = app.get("responseTypes", [])
    grant_types = app.get("grantTypes", [])
    app_type = app.get("appType")
    auth_method = app.get("authMethodType")

    if not isinstance(name, str) or not name:
        logger.error(
            "OIDC app entry missing required 'name' field. Got: %s. "
            "Fix: regenerate the provisioning artifact.",
            app,
        )
        sys.exit(1)

    payload: dict[str, Any] = {
        "name": name,
        "redirectUris": redirect_uris,
        "responseTypes": response_types,
        "grantTypes": grant_types,
        "appType": app_type,
        "authMethodType": auth_method,
    }
    payload.update(_oidc_preserved_fields(app))
    url = "%s/projects/%s/apps/oidc" % (api.mgmt_base, project_id)
    status, body = _json_request(url, api, method="POST", payload=payload)
    if status not in (200, 201):
        logger.error(
            "Failed to create OIDC app '%s' in project=%s (HTTP %d): %s.",
            name,
            project_id,
            status,
            body,
        )
        sys.exit(1)
    app_id = body.get("appId")
    if not isinstance(app_id, str) or not app_id:
        logger.error(
            "Create OIDC app '%s' response missing 'appId'. Got: %s.",
            name,
            body,
        )
        sys.exit(1)
    logger.info("oidc_app_created project=%s name=%s appId=%s", project_id, name, app_id)
    return app_id


def _update_oidc_app(
    api: _Api,
    project_id: str,
    app_id: str,
    app: dict[str, Any],
) -> None:
    """Update OIDC config on an existing app.

    Zitadel's OIDC-app *create* endpoint is ``POST .../apps/oidc``, but the
    *update* endpoint is ``PUT .../apps/{appId}/oidc_config`` (different suffix).
    Using ``/oidc`` for the update returns HTTP 404.

    Raises:
        SystemExit(1): On API error.
    """
    url = "%s/projects/%s/apps/%s/oidc_config" % (api.mgmt_base, project_id, app_id)
    payload: dict[str, Any] = {
        "redirectUris": app.get("redirectUris", []),
        "responseTypes": app.get("responseTypes", []),
        "grantTypes": app.get("grantTypes", []),
        "appType": app.get("appType"),
        "authMethodType": app.get("authMethodType"),
    }
    payload.update(_oidc_preserved_fields(app))
    status, body = _json_request(url, api, method="PUT", payload=payload)
    if status not in (200, 201) and not _is_no_changes(status, body):
        logger.error(
            "Failed to update OIDC app id=%s in project=%s (HTTP %d): %s.",
            app_id,
            project_id,
            status,
            body,
        )
        sys.exit(1)
    logger.info("oidc_app_updated project=%s appId=%s", project_id, app_id)


def _read_minted_client_id(
    api: _Api,
    project_id: str,
    app_id: str,
    name: str,
) -> str:
    """Read the OIDC client id Zitadel minted for an app.

    Zitadel generates ``OIDCConfig.clientId`` when the app is created (its own
    documentation calls it the "generated oauth2/oidc client id") and generates a
    new one whenever the app is recreated.  The instance is therefore the only
    authority for the current value, and it is read back here rather than assumed
    from anything in the artifact.

    Args:
        api: Connection context.
        project_id: Zitadel project ID.
        app_id: The application's Zitadel ID.
        name: The application name, for error messages.

    Returns:
        The minted client id.

    Raises:
        SystemExit(1): On API error, or when the response carries no OIDC client
            id -- a consumer left holding a stale or empty id fails only at a
            browser sign-in, so this fails here instead.
    """
    url = "%s/projects/%s/apps/%s" % (api.mgmt_base, project_id, app_id)
    status, body = _json_request(url, api)
    if status != 200:
        logger.error(
            "Failed to read OIDC app '%s' (id=%s) in project=%s to resolve its "
            "minted client id (HTTP %d): %s.",
            name,
            app_id,
            project_id,
            status,
            body,
        )
        sys.exit(1)
    app = body.get("app")
    oidc_config = app.get("oidcConfig") if isinstance(app, dict) else None
    client_id = oidc_config.get("clientId") if isinstance(oidc_config, dict) else None
    if not isinstance(client_id, str) or not client_id:
        logger.error(
            "OIDC app '%s' (id=%s) carries no minted clientId. Got: %s. "
            "Fix: confirm the app was created as an OIDC application (not API or "
            "SAML) -- only an OIDC app has a client id to bind.",
            name,
            app_id,
            body,
        )
        sys.exit(1)
    return client_id


def _write_minted_client_id(path: str, client_id: str, name: str) -> None:
    """Write a minted OIDC client id where its consumer reads it.

    The file is written world-READABLE (``0644``) and left owned by root, unlike
    the machine-credentials file beside it.  That is deliberate: an OIDC client
    id is a public identifier -- it travels in every browser's authorize URL --
    and its consumers are stock third-party images running as their own uids
    (Grafana's is 472), which no chown here could enumerate.  Nothing secret is
    written to this volume; the values that are secret keep their own volume,
    their own ``0600`` mode, and their own owner.

    Args:
        path: Absolute container path from the artifact's ``clientIdFile``.
        client_id: The minted client id.
        name: The application name, for the log line and error messages.

    Raises:
        SystemExit(1): When the file cannot be written.  A consumer that reads
            nothing here presents no client id and is refused at authorize, so
            the deployment must fail at provisioning instead of at first
            sign-in.
    """
    directory = os.path.dirname(path)
    try:
        if directory and not os.path.exists(directory):
            os.makedirs(directory, exist_ok=True)
        with open(path, "w", encoding="utf-8") as fh:
            fh.write(client_id)
        os.chmod(path, 0o644)
    except OSError as exc:
        logger.error(
            "Failed to write the minted OIDC client id for app '%s' to '%s': %s. "
            "Fix: the init container must mount the minted-client-id volume "
            "read-write at that path; without the file its consumer starts with "
            "no client id and every sign-in is refused.",
            name,
            path,
            exc,
        )
        sys.exit(1)
    logger.info(
        "oidc_client_id_written app=%s path=%s clientId=%s", name, path, client_id
    )


def _bind_minted_client_id(
    api: _Api,
    project_id: str,
    app_id: str,
    app: dict[str, Any],
) -> None:
    """Write back the minted client id when the app entry declares a target.

    Only apps whose artifact entry carries ``clientIdFile`` have a consumer that
    needs the minted value; every other app is reached by name alone.  Runs on
    create AND update, because a re-provision against a reset instance recreates
    the app with a NEW client id while the artifact is unchanged.

    Args:
        api: Connection context.
        project_id: Zitadel project ID.
        app_id: The application's Zitadel ID.
        app: OIDC app dict from the artifact.
    """
    target = app.get("clientIdFile")
    if target is None:
        return
    name = str(app.get("name"))
    if not isinstance(target, str) or not target:
        logger.error(
            "OIDC app '%s' declares an empty 'clientIdFile'. Got: %s. "
            "Fix: regenerate the provisioning artifact.",
            name,
            target,
        )
        sys.exit(1)
    client_id = _read_minted_client_id(api, project_id, app_id, name)
    _write_minted_client_id(target, client_id, name)


def _ensure_oidc_apps(
    api: _Api,
    project_id: str,
    oidc_apps: list[dict[str, Any]],
) -> None:
    """Idempotently create or update OIDC apps for a project.

    ``name`` is the app KEY: it is what an existing app is matched by and what a
    missing one is created as.  Zitadel mints the client id itself, so an app
    whose entry declares a ``clientIdFile`` has that minted value written back
    afterwards (see :func:`_bind_minted_client_id`).

    Args:
        api: Connection context.
        project_id: Zitadel project ID.
        oidc_apps: List of OIDC app dicts from the artifact.
    """
    existing = _list_apps(api, project_id)
    existing_by_name: dict[str, dict[str, Any]] = {
        a.get("name", ""): a for a in existing
    }

    for app in oidc_apps:
        name = app.get("name")
        if not isinstance(name, str) or not name:
            logger.error(
                "OIDC app entry missing 'name'. Got: %s. "
                "Fix: regenerate the provisioning artifact.",
                app,
            )
            sys.exit(1)
        if name in existing_by_name:
            existing_app = existing_by_name[name]
            app_id = existing_app.get("id")
            if not isinstance(app_id, str) or not app_id:
                logger.error(
                    "Existing app '%s' has no id. Got: %s.",
                    name,
                    existing_app,
                )
                sys.exit(1)
            _update_oidc_app(api, project_id, app_id, app)
        else:
            app_id = _create_oidc_app(api, project_id, app)
        _bind_minted_client_id(api, project_id, app_id, app)


# ---------------------------------------------------------------------------
# Machine (service-account) provisioning
# ---------------------------------------------------------------------------

#: Access-token type for the inter-service machine user. JWT (not the default
#: opaque Bearer) is required so the callee can validate the inter-service token
#: via JWKS — an opaque token cannot be JWKS-validated.
_MACHINE_ACCESS_TOKEN_TYPE: str = "ACCESS_TOKEN_TYPE_JWT"

#: UID/GID of the non-root ``appuser`` that every generated backend service
#: container runs as (the Python service Dockerfile creates it with
#: ``--uid 1000 --gid 1000`` and runs ``USER appuser``).  This applier runs as
#: **root** in the Zitadel init container, so the shared machine-credentials file
#: it writes is chowned to this uid/gid — otherwise the ``0600`` file written by
#: root is unreadable by the non-root service users that must read it, and every
#: ``auth(service)`` call fails with PermissionError.  MUST stay in sync with the
#: appuser uid in the generated Python service Dockerfile.
_SERVICE_USER_UID: int = 1000


def _find_machine_user(api: _Api, user_name: str) -> str | None:
    """Return the existing machine user's id for *user_name*, or ``None``."""
    url = api.mgmt_base + "/users/_search"
    payload: dict[str, Any] = {
        "queries": [
            {
                "userNameQuery": {
                    "userName": user_name,
                    "method": "TEXT_QUERY_METHOD_EQUALS",
                }
            }
        ]
    }
    status, body = _json_request(url, api, method="POST", payload=payload)
    if status not in (200, 404):
        logger.error(
            "Failed to search users for '%s' (HTTP %d): %s.",
            user_name,
            status,
            body,
        )
        sys.exit(1)
    result = body.get("result")
    if isinstance(result, list):
        for user in result:
            user_id = user.get("id") if isinstance(user, dict) else None
            if isinstance(user_id, str) and user_id:
                return user_id
    return None


def _create_machine_user(api: _Api, user_name: str, name: str) -> str:
    """Create a JWT-token machine (service-account) user and return its id.

    Raises:
        SystemExit(1): On API error or missing ``userId`` in the response.
    """
    url = api.mgmt_base + "/users/machine"
    payload: dict[str, Any] = {
        "userName": user_name,
        "name": name,
        "accessTokenType": _MACHINE_ACCESS_TOKEN_TYPE,
    }
    status, body = _json_request(url, api, method="POST", payload=payload)
    if status not in (200, 201):
        logger.error(
            "Failed to create machine user '%s' (HTTP %d): %s.",
            user_name,
            status,
            body,
        )
        sys.exit(1)
    user_id = body.get("userId")
    if not isinstance(user_id, str) or not user_id:
        logger.error(
            "Create machine user '%s' response missing 'userId'. Got: %s.",
            user_name,
            body,
        )
        sys.exit(1)
    logger.info("machine_user_created userName=%s id=%s", user_name, user_id)
    return user_id


def _ensure_machine_user(api: _Api, user_name: str, name: str) -> str:
    """Idempotently get-or-create the inter-service machine user."""
    existing = _find_machine_user(api, user_name)
    if existing is not None:
        logger.info("machine_user_exists userName=%s id=%s", user_name, existing)
        return existing
    return _create_machine_user(api, user_name, name)


def _find_org_member_roles(api: _Api, user_id: str) -> list[str] | None:
    """Return the existing org member's granted roles, or ``None`` if not a member.

    Uses ``POST /orgs/me/members/_search`` (ListOrgMembers) -- the org-member
    endpoints have no filter-by-single-user GET, matching every other list call
    in this applier (projects/roles/apps/actions all use ``_search``).

    Raises:
        SystemExit(1): On a non-200/404 API error.
    """
    url = api.mgmt_base + "/orgs/me/members/_search"
    payload: dict[str, Any] = {"queries": [{"userIdQuery": {"userId": user_id}}]}
    status, body = _json_request(url, api, method="POST", payload=payload)
    if status not in (200, 404):
        logger.error(
            "Failed to list org members for user_id=%s (HTTP %d): %s. "
            "Fix: verify the machine-user PAT has org-level permissions.",
            user_id,
            status,
            body,
        )
        sys.exit(1)
    result = body.get("result")
    if isinstance(result, list):
        for member in result:
            if isinstance(member, dict) and member.get("userId") == user_id:
                roles = member.get("roles")
                if isinstance(roles, list):
                    return [r for r in roles if isinstance(r, str)]
                return []
    return None


def _ensure_org_user_manager_grant(api: _Api, user_id: str) -> None:
    """Idempotently grant the machine service account org-level metadata-write access.

    The generated runtime's Management-API metadata writer (a separate task)
    authenticates as this SAME machine service account via its
    own client_credentials token -- a different authorization path from the
    inter-service JWKS guard.  Without ``ORG_USER_MANAGER``,
    every metadata write is rejected and the syncOnAuth claim never appears --
    a silent tenancy outage (Risk 2).  Call only when the artifact's
    ``machineUser.grantsMetadataWrite`` is true.

    Raises:
        SystemExit(1): On any non-recoverable Management API error.
    """
    existing_roles = _find_org_member_roles(api, user_id)
    if existing_roles is None:
        url = api.mgmt_base + "/orgs/me/members"
        payload: dict[str, Any] = {
            "userId": user_id,
            "roles": [_ORG_USER_MANAGER_ROLE],
        }
        status, body = _json_request(url, api, method="POST", payload=payload)
        if status not in (200, 201) and not _is_no_changes(status, body):
            logger.error(
                "Failed to add org member grant for user_id=%s (HTTP %d): %s.",
                user_id,
                status,
                body,
            )
            sys.exit(1)
        logger.info("org_user_manager_grant_added user_id=%s", user_id)
        return
    if _ORG_USER_MANAGER_ROLE in existing_roles:
        logger.info("org_user_manager_grant_exists user_id=%s", user_id)
        return
    url = "%s/orgs/me/members/%s" % (api.mgmt_base, user_id)
    payload = {"roles": existing_roles + [_ORG_USER_MANAGER_ROLE]}
    status, body = _json_request(url, api, method="PUT", payload=payload)
    if status not in (200, 201) and not _is_no_changes(status, body):
        logger.error(
            "Failed to update org member grant for user_id=%s (HTTP %d): %s.",
            user_id,
            status,
            body,
        )
        sys.exit(1)
    logger.info(
        "org_user_manager_grant_updated user_id=%s roles=%s", user_id, payload["roles"]
    )


def _generate_machine_secret(api: _Api, user_id: str) -> tuple[str, str]:
    """Generate the machine user's client secret; return ``(clientId, clientSecret)``.

    Zitadel issues the secret once per call and rotates it on each call, so the
    applier rewrites the credentials file on every run; backend services depend on
    the init-job completing, so they always read the current secret.

    Raises:
        SystemExit(1): On API error or missing fields in the response.
    """
    url = "%s/users/%s/secret" % (api.mgmt_base, user_id)
    status, body = _json_request(url, api, method="PUT", payload={})
    if status not in (200, 201):
        logger.error(
            "Failed to generate machine secret for user id=%s (HTTP %d): %s.",
            user_id,
            status,
            body,
        )
        sys.exit(1)
    client_id = body.get("clientId")
    client_secret = body.get("clientSecret")
    if (
        not isinstance(client_id, str)
        or not client_id
        or not isinstance(client_secret, str)
        or not client_secret
    ):
        logger.error(
            "Generate machine secret for user id=%s response missing "
            "clientId/clientSecret. Got keys: %s.",
            user_id,
            sorted(body.keys()),
        )
        sys.exit(1)
    logger.info("machine_secret_generated user_id=%s clientId=%s", user_id, client_id)
    return client_id, client_secret


def _provision_machine_user(
    api: _Api,
    project: dict[str, Any],
    project_id: str,
) -> dict[str, str] | None:
    """Provision the machine user for a project and return its credential material.

    Returns ``None`` when the project declares no ``machineUser`` (non-machine
    audiences).  The returned dict carries three keys — ``clientId``,
    ``clientSecret``, and the reserved project-audience ``audience`` scope the
    caller requests so the issued token's ``aud`` matches the callee's
    ``allowedAudiences``.  The deployment-static ``tokenUrl`` and ``hostHeader``
    are added by ``main()`` before the credentials are persisted, so this
    function does not need them in scope.

    Raises:
        SystemExit(1): When ``machineUser`` is present but malformed.
    """
    machine_user = project.get("machineUser")
    if machine_user is None:
        return None
    if not isinstance(machine_user, dict):
        logger.error(
            "Project '%s' has a non-object 'machineUser'. Got: %s. "
            "Fix: regenerate the provisioning artifact.",
            project.get("name"),
            machine_user,
        )
        sys.exit(1)
    user_name = machine_user.get("userName")
    if not isinstance(user_name, str) or not user_name:
        logger.error(
            "Project '%s' machineUser is missing 'userName'. Got: %s.",
            project.get("name"),
            machine_user,
        )
        sys.exit(1)
    display_name = machine_user.get("name")
    if not isinstance(display_name, str) or not display_name:
        display_name = user_name
    user_id = _ensure_machine_user(api, user_name, display_name)
    if bool(machine_user.get("grantsMetadataWrite", False)) or bool(
        machine_user.get("grantsUserAdministration", False)
    ):
        _ensure_org_user_manager_grant(api, user_id)
    client_id, client_secret = _generate_machine_secret(api, user_id)
    return {
        "clientId": client_id,
        "clientSecret": client_secret,
        "audience": _machine_audience_scope(project_id),
    }


def _machine_audience_scope(project_id: str) -> str:
    """The reserved scope that puts *project_id* into a machine token's ``aud``."""
    return "urn:zitadel:iam:org:project:id:%s:aud" % project_id


def _write_machine_credentials(path: str, credentials: Mapping[str, object]) -> None:
    """Write the inter-service machine credentials JSON to *path*, owned by the service user.

    Backend services read this file (``IDENTITY_MACHINE_CREDENTIALS_FILE``) to
    perform the OAuth2 client_credentials exchange.  This applier runs as **root**
    in the Zitadel init container, but every backend service runs as the non-root
    ``appuser`` (uid ``_SERVICE_USER_UID``) with a read-only mount — so a file left
    ``root:root`` ``0600`` is unreadable by exactly the processes that must read it
    (``PermissionError``).  The file is therefore chowned to the service uid/gid;
    mode ``0600`` is kept, so ownership — not a broader world-readable mode — is
    what grants the read.  The secret is never logged.
    """
    directory = os.path.dirname(path)
    if directory and not os.path.exists(directory):
        os.makedirs(directory, exist_ok=True)
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(credentials, fh)
    try:
        os.chmod(path, 0o600)
    except OSError as exc:
        # The file holds a client secret: a mode left to the umask would expose it more
        # widely than intended, so the failure stops the init container.
        logger.error(
            "Failed to restrict machine credentials '%s' to mode 0600: %s. "
            "Fix: the init container must be able to change the mode of files it writes "
            "to the credentials volume.",
            path,
            exc,
        )
        sys.exit(1)
    # Hand the file to the non-root service user (uid/gid _SERVICE_USER_UID) that
    # consumes it.  This applier runs as root in the init container, so the chown
    # succeeds; if it does not, the credentials file stays unreadable by every
    # backend service, so fail loud rather than ship a deployment whose
    # inter-service auth is silently broken.
    try:
        # `os.chown` is POSIX-only, so a type checker running on Windows -- where
        # this module is only ever IMPORTED, never executed -- does not see it on
        # `os`. The inlined copy of this source runs exclusively in the Linux init
        # container, where the call is real and its failure is fatal below.
        os.chown(path, _SERVICE_USER_UID, _SERVICE_USER_UID)  # type: ignore[attr-defined]
    except OSError as exc:
        logger.error(
            "Failed to chown machine credentials '%s' to uid/gid %d: %s. "
            "Fix: the Zitadel init container must run as root so the credentials "
            "file it writes is readable by the non-root service user (uid %d) that "
            "performs the inter-service OAuth2 client_credentials exchange.",
            path,
            _SERVICE_USER_UID,
            exc,
            _SERVICE_USER_UID,
        )
        sys.exit(1)
    logger.info(
        "machine_credentials_written path=%s clientId=%s",
        path,
        credentials.get("clientId"),
    )


# ---------------------------------------------------------------------------
# Social IdP provisioning
# ---------------------------------------------------------------------------


def _list_idps(api: _Api) -> list[dict[str, Any]]:
    """Fetch all existing IdP configs at the instance level."""
    url = api.mgmt_base + "/idps/_search"
    status, body = _json_request(url, api, method="POST", payload={})
    if status not in (200, 404):
        logger.error(
            "Failed to list IdPs (HTTP %d): %s. "
            "Fix: verify the machine-user PAT has iam-level permissions.",
            status,
            body,
        )
        sys.exit(1)
    result = body.get("result")
    if isinstance(result, list):
        return result
    return []


def _resolve_secret_ref(ref: str, owner: str) -> str:
    """Resolve a secret reference to its runtime value.

    Supports:
      - ``${VAR_NAME}``  -> reads ``os.environ["VAR_NAME"]``
      - ``/run/secrets/<name>`` -> reads file content

    Args:
        ref: The secret reference string from the artifact.
        owner: What holds the reference (``Social IdP 'google'``), for error messages.

    Returns:
        The resolved secret value string.

    Raises:
        SystemExit(1): When the env var is absent, the file does not exist, or
            the ref format is not recognised.
    """
    if ref.startswith("${") and ref.endswith("}"):
        var_name = ref[2:-1]
        value = os.environ.get(var_name, "").strip()
        if not value:
            logger.error(
                "%s references env var '%s' which is absent or empty. "
                "Fix: ensure the init-job container populates this env var from a "
                "secret ref before the applier runs.",
                owner,
                var_name,
            )
            sys.exit(1)
        return value
    if ref.startswith("/run/secrets/"):
        secret_path = ref
        if not os.path.exists(secret_path):
            logger.error(
                "%s references docker secret file '%s' which does not exist. "
                "Fix: ensure the init-job mounts the secret at this path.",
                owner,
                secret_path,
            )
            sys.exit(1)
        with open(secret_path, "r", encoding="utf-8") as fh:
            return fh.read().strip()
    logger.error(
        "%s has an unrecognised secret reference format '%s'. "
        "Valid formats: '${VAR_NAME}' (env var) or '/run/secrets/<name>' "
        "(docker secret). Fix: regenerate the provisioning artifact with a "
        "valid secretRef provider ('env' or 'docker-secret').",
        owner,
        ref,
    )
    sys.exit(1)


#: The Management API path segment of a social IdP type that is not the type's lowercase name
#: without underscores (``POST /management/v1/idps/azure`` adds an Azure AD provider).
_IDP_PATH_SEGMENT_OVERRIDES: dict[str, str] = {"AZURE_AD": "azure"}

#: ``tenantType`` of an Azure AD provider whose authority is a family of tenants.
_AZURE_TENANT_TYPES: dict[str, str] = {
    "common": "AZURE_AD_TENANT_TYPE_COMMON",
    "organizations": "AZURE_AD_TENANT_TYPE_ORGANISATIONS",
    "consumers": "AZURE_AD_TENANT_TYPE_CONSUMERS",
}


def _idp_path_segment(idp_type: str) -> str:
    """The path segment the Management API adds an IdP of *idp_type* under."""
    return _IDP_PATH_SEGMENT_OVERRIDES.get(idp_type, idp_type.lower().replace("_", ""))


def _social_idp_payload(idp: Mapping[str, object], client_secret: str) -> dict[str, object]:
    """The create/update body of one social IdP.

    An Azure AD provider also names its sign-in authority: a family of tenants by
    ``tenantType``, or one tenant by ``tenantId``.
    """
    payload: dict[str, object] = {
        "name": idp.get("name", "unknown"),
        "clientId": idp.get("clientId"),
        "clientSecret": client_secret,
    }
    tenant = idp.get("tenant")
    if tenant is not None:
        tenant_type = _AZURE_TENANT_TYPES.get(str(tenant))
        payload["tenant"] = (
            {"tenantType": tenant_type} if tenant_type is not None else {"tenantId": tenant}
        )
    return payload


def _create_social_idp(
    api: _Api,
    idp: dict[str, Any],
    client_secret: str,
) -> str:
    """Create a social IdP at the instance level and return its ``idpId``.

    Args:
        api: Connection context.
        idp: IdP dict from the artifact (``name``, ``type``, ``clientId``).
        client_secret: Resolved client secret value.

    Returns:
        The new IdP's ``idpId`` string.

    Raises:
        SystemExit(1): On unsupported type or API error.
    """
    idp_type = idp.get("type")
    idp_name = idp.get("name", "unknown")

    if idp_type not in _SUPPORTED_IDP_TYPES:
        logger.error(
            "Social IdP '%s' has unsupported type '%s'. "
            "Supported types: %s. "
            "Fix: use a valid social provider type in the identity config.",
            idp_name,
            idp_type,
            sorted(_SUPPORTED_IDP_TYPES),
        )
        sys.exit(1)

    url = "%s/idps/%s" % (api.mgmt_base, _idp_path_segment(str(idp_type)))
    payload = _social_idp_payload(idp, client_secret)
    status, body = _json_request(url, api, method="POST", payload=payload)
    if status not in (200, 201):
        logger.error(
            "Failed to create social IdP '%s' type=%s (HTTP %d): %s.",
            idp_name,
            idp_type,
            status,
            body,
        )
        sys.exit(1)
    idp_id = body.get("idpId") or body.get("id")
    if not isinstance(idp_id, str) or not idp_id:
        logger.error(
            "Create IdP '%s' response missing 'idpId'. Got: %s.",
            idp_name,
            body,
        )
        sys.exit(1)
    logger.info("social_idp_created name=%s type=%s idpId=%s", idp_name, idp_type, idp_id)
    return idp_id


def _update_social_idp(
    api: _Api,
    idp_id: str,
    idp: dict[str, Any],
    client_secret: str,
) -> None:
    """Update an existing social IdP at the instance level.

    Raises:
        SystemExit(1): On unsupported type or API error.
    """
    idp_type = idp.get("type")
    idp_name = idp.get("name", "unknown")

    if idp_type not in _SUPPORTED_IDP_TYPES:
        logger.error(
            "Social IdP '%s' has unsupported type '%s'. "
            "Supported types: %s. "
            "Fix: use a valid social provider type.",
            idp_name,
            idp_type,
            sorted(_SUPPORTED_IDP_TYPES),
        )
        sys.exit(1)

    url = "%s/idps/%s/%s" % (api.mgmt_base, _idp_path_segment(str(idp_type)), idp_id)
    payload = _social_idp_payload(idp, client_secret)
    status, body = _json_request(url, api, method="PUT", payload=payload)
    if status not in (200, 201) and not _is_no_changes(status, body):
        logger.error(
            "Failed to update social IdP id=%s name=%s (HTTP %d): %s.",
            idp_id,
            idp_name,
            status,
            body,
        )
        sys.exit(1)
    logger.info("social_idp_updated name=%s idpId=%s", idp_name, idp_id)


def _ensure_social_idps(
    api: _Api,
    identity_providers: list[dict[str, Any]],
) -> list[str]:
    """Idempotently create or update social IdPs at the Zitadel instance level.

    Args:
        api: Connection context.
        identity_providers: List of IdP dicts from the artifact.

    Returns:
        The id of each IdP, in the artifact's order.
    """
    idp_ids: list[str] = []
    existing = _list_idps(api)
    existing_by_name: dict[str, dict[str, Any]] = {
        p.get("name", ""): p for p in existing
    }

    for idp in identity_providers:
        idp_name = idp.get("name")
        secret_ref = idp.get("clientSecretRef")

        if not isinstance(idp_name, str) or not idp_name:
            logger.error(
                "Identity provider entry missing 'name'. Got: %s. "
                "Fix: regenerate the provisioning artifact.",
                idp,
            )
            sys.exit(1)
        if not isinstance(secret_ref, str) or not secret_ref:
            logger.error(
                "Identity provider '%s' missing 'clientSecretRef'. Got: %s. "
                "Fix: ensure socialProviders[].clientSecret is declared in the "
                "identity config with an 'env' or 'docker-secret' provider.",
                idp_name,
                idp,
            )
            sys.exit(1)

        client_secret = _resolve_secret_ref(secret_ref, "Social IdP '%s'" % idp_name)

        if idp_name in existing_by_name:
            existing_idp = existing_by_name[idp_name]
            idp_id = existing_idp.get("id")
            if not isinstance(idp_id, str) or not idp_id:
                logger.error(
                    "Existing IdP '%s' has no id. Got: %s.",
                    idp_name,
                    existing_idp,
                )
                sys.exit(1)
            _update_social_idp(api, idp_id, idp, client_secret)
            idp_ids.append(idp_id)
        else:
            idp_ids.append(_create_social_idp(api, idp, client_secret))
    return idp_ids


# ---------------------------------------------------------------------------
# Token-claim-injection action (Complement Token flow)
# ---------------------------------------------------------------------------


def _token_claim_value_expr(source: str) -> str:
    """Return the JS value expression for a profile or metadata source kind.

    A ``metadata:<key>`` source reads the app-owned value the
    generated runtime wrote into the user's provider
    metadata, via the ``metadataMap`` lookup ``_build_token_claim_script``
    builds from ``ctx.v1.user.getMetadata().metadata`` -- independent of
    ``ctx.v1.getUser().human`` (metadata exists for every principal, not only
    human ones).  The value is read VERBATIM, with no decode: the Management-API
    write side base64-encodes the request body, but Zitadel v3 base64-*decodes*
    it once on write and stores the raw bytes, so ``getMetadata()`` inside the
    action already surfaces the original plain value.  Decoding it a second time
    here would corrupt it (proven on live Zitadel v3.0.0 staging: single-encode
    write + action decode yielded a garbage ``organizationId``); the round-trip
    is identity only when the action reads the metadata value as-is.

    Args:
        source: The ``tokenClaimAction.claims[].source`` kind from the artifact.

    Returns:
        The JavaScript expression that reads the value -- off the
        ``human``/``user`` profile object for a profile source, or the raw
        ``metadataMap`` lookup for a ``metadata:<key>`` source.

    Raises:
        SystemExit(1): When a non-metadata source kind is not recognised
            (artifact/applier version skew).
    """
    if source.startswith(_METADATA_CLAIM_SOURCE_PREFIX):
        key = source[len(_METADATA_CLAIM_SOURCE_PREFIX):]
        return "metadataMap[%s]" % json.dumps(key)
    expr = _TOKEN_CLAIM_SOURCE_EXPRESSIONS.get(source)
    if expr is None:
        logger.error(
            "tokenClaimAction claim has unknown source kind '%s'. Known kinds: %s "
            "(plus any 'metadata:<key>' source). "
            "Fix: regenerate the provisioning artifact with the matching "
            "cruftfree-codegen-docker version.",
            source,
            sorted(_TOKEN_CLAIM_SOURCE_EXPRESSIONS),
        )
        sys.exit(1)
    return expr


def _profile_claim_lines(claim_name: str, source: str) -> list[str]:
    """Return the action statements that stamp one profile-sourced claim.

    A boolean source is stamped as a boolean on every human token; every other
    source is stamped only when the profile holds a value for it.
    """
    expr = _token_claim_value_expr(source)
    quoted = json.dumps(claim_name)
    if source in _TOKEN_CLAIM_BOOLEAN_SOURCES:
        return [
            "    value = !!(%s);" % expr,
            "    api.v1.claims.setClaim(%s, value);" % quoted,
        ]
    return [
        "    value = %s;" % expr,
        "    if (value) { api.v1.claims.setClaim(%s, value); }" % quoted,
    ]


def _build_token_claim_script(action_name: str, claims: list[dict[str, Any]]) -> str:
    """Build the Complement-Token action JavaScript from the artifact claim list.

    Zitadel invokes the JS function whose identifier EQUALS the action name, so
    the emitted function is named *action_name* verbatim.  Profile-sourced
    claims read ``ctx.v1.getUser().human`` and are skipped entirely for a
    principal with no human profile (machine tokens).  Metadata-sourced claims
    read ``ctx.v1.user.getMetadata()`` -- a DIFFERENT, always-
    available API surface -- so they run regardless of whether the principal
    has a human profile.  Metadata values are stamped verbatim (Zitadel v3
    decodes the base64 request body on write and stores the raw value, so the
    action must not decode again -- see ``_token_claim_value_expr``).

    Args:
        action_name: The action name (also the JS function identifier).
        claims: List of ``{"claim": <claimPath>, "source": <kind>}`` dicts.

    Returns:
        The action script as a JavaScript source string.

    Raises:
        SystemExit(1): When a claim entry is missing ``claim``/``source``, or
            names an unrecognised non-metadata source kind.
    """
    validated: list[tuple[str, str]] = []
    for claim in claims:
        claim_name = claim.get("claim")
        source = claim.get("source")
        if not isinstance(claim_name, str) or not claim_name:
            logger.error(
                "tokenClaimAction claim entry is missing 'claim'. Got: %s. "
                "Fix: regenerate the provisioning artifact.",
                claim,
            )
            sys.exit(1)
        if not isinstance(source, str) or not source:
            logger.error(
                "tokenClaimAction claim entry is missing 'source'. Got: %s. "
                "Fix: regenerate the provisioning artifact.",
                claim,
            )
            sys.exit(1)
        validated.append((claim_name, source))

    profile_claims = [
        (n, s) for n, s in validated if not s.startswith(_METADATA_CLAIM_SOURCE_PREFIX)
    ]
    metadata_claims = [
        (n, s) for n, s in validated if s.startswith(_METADATA_CLAIM_SOURCE_PREFIX)
    ]

    lines: list[str] = ["function %s(ctx, api) {" % action_name]
    if profile_claims:
        lines += [
            "  var user = ctx.v1.getUser();",
            "  if (user && user.human) {",
            "    var human = user.human;",
            "    var value;",
        ]
        for claim_name, source in profile_claims:
            lines += _profile_claim_lines(claim_name, source)
        lines.append("  }")
    if metadata_claims:
        lines += [
            "  var metadataMap = {};",
            "  ctx.v1.user.getMetadata().metadata.forEach(function (entry) {",
            "    metadataMap[entry.key] = entry.value;",
            "  });",
            "  var metaValue;",
        ]
        for claim_name, source in metadata_claims:
            lines.append("  metaValue = %s;" % _token_claim_value_expr(source))
            lines.append(
                "  if (metaValue) { api.v1.claims.setClaim(%s, metaValue); }"
                % json.dumps(claim_name)
            )
    lines.append("}")
    return "\n".join(lines)


def _list_actions(api: _Api) -> list[dict[str, Any]]:
    """Fetch all existing org-level actions (POST /actions/_search)."""
    url = api.mgmt_base + "/actions/_search"
    status, body = _json_request(url, api, method="POST", payload={})
    if status not in (200, 404):
        logger.error(
            "Failed to list actions (HTTP %d): %s. "
            "Fix: verify the machine-user PAT has org-level permissions.",
            status,
            body,
        )
        sys.exit(1)
    result = body.get("result")
    if isinstance(result, list):
        return result
    return []


def _create_action(api: _Api, name: str, script: str) -> str:
    """Create the claim-injection action and return its id (POST /actions).

    ``allowedToFail`` is true so a transient action error degrades to Zitadel's
    prior behaviour (no claim stamped) instead of failing ALL token issuance.

    Raises:
        SystemExit(1): On API error or a response missing ``id``.
    """
    url = api.mgmt_base + "/actions"
    payload: dict[str, Any] = {
        "name": name,
        "script": script,
        "timeout": _TOKEN_CLAIM_ACTION_TIMEOUT,
        "allowedToFail": True,
    }
    status, body = _json_request(url, api, method="POST", payload=payload)
    if status not in (200, 201):
        logger.error(
            "Failed to create action '%s' (HTTP %d): %s.",
            name,
            status,
            body,
        )
        sys.exit(1)
    action_id = body.get("id")
    if not isinstance(action_id, str) or not action_id:
        logger.error(
            "Create action '%s' response missing 'id'. Got: %s.",
            name,
            body,
        )
        sys.exit(1)
    logger.info("action_created name=%s id=%s", name, action_id)
    return action_id


def _update_action(api: _Api, action_id: str, name: str, script: str) -> None:
    """Update the claim-injection action (PUT /actions/{id}).

    Re-asserts name/script/timeout/allowedToFail so a converged re-run keeps the
    action current.  Zitadel's "No changes" 400 on an unchanged re-apply is success.

    Raises:
        SystemExit(1): On API error.
    """
    url = "%s/actions/%s" % (api.mgmt_base, action_id)
    payload: dict[str, Any] = {
        "name": name,
        "script": script,
        "timeout": _TOKEN_CLAIM_ACTION_TIMEOUT,
        "allowedToFail": True,
    }
    status, body = _json_request(url, api, method="PUT", payload=payload)
    if status not in (200, 201) and not _is_no_changes(status, body):
        logger.error(
            "Failed to update action id=%s name=%s (HTTP %d): %s.",
            action_id,
            name,
            status,
            body,
        )
        sys.exit(1)
    logger.info("action_updated id=%s name=%s", action_id, name)


def _set_trigger_actions(
    api: _Api,
    flow_type: str,
    trigger_type: str,
    action_ids: list[str],
) -> None:
    """Bind *action_ids* to a flow trigger (POST /flows/{flow}/trigger/{trigger}).

    This is a full-replace SET of the actions on the given trigger, so it is
    idempotent: re-applying the same ``action_ids`` converges to the same binding.
    CruftFree owns provisioning, so no externally-managed action is clobbered.

    Raises:
        SystemExit(1): On API error.
    """
    url = "%s/flows/%s/trigger/%s" % (api.mgmt_base, flow_type, trigger_type)
    payload: dict[str, Any] = {"actionIds": action_ids}
    status, body = _json_request(url, api, method="POST", payload=payload)
    if status not in (200, 201) and not _is_no_changes(status, body):
        logger.error(
            "Failed to set trigger actions flow=%s trigger=%s (HTTP %d): %s.",
            flow_type,
            trigger_type,
            status,
            body,
        )
        sys.exit(1)
    logger.info(
        "trigger_actions_set flow=%s trigger=%s actions=%s",
        flow_type,
        trigger_type,
        action_ids,
    )


def _ensure_token_claim_action(api: _Api, action_spec: dict[str, Any]) -> None:
    """Idempotently converge the Complement-Token claim-injection action + bindings.

    Creates (or updates) the org-level action whose JS stamps the profile-sourced
    identity-field claims onto issued tokens, then binds it to the
    PreUserinfoCreation and PreAccessTokenCreation triggers of the Complement-Token
    flow.  Without this binding Zitadel's default access token carries no ``email``/
    ``name`` claim and the auth service rejects every human token with
    ``required_identity_field_missing``.

    Args:
        api: Connection context.
        action_spec: The artifact ``tokenClaimAction`` block
            (``{"name": str, "claims": list}``).

    Raises:
        SystemExit(1): When the spec is malformed or any API call fails.
    """
    name = action_spec.get("name")
    claims = action_spec.get("claims")
    if not isinstance(name, str) or not name:
        logger.error(
            "tokenClaimAction is missing 'name'. Got: %s. "
            "Fix: regenerate the provisioning artifact.",
            action_spec,
        )
        sys.exit(1)
    if not isinstance(claims, list) or not claims:
        logger.error(
            "tokenClaimAction is missing a non-empty 'claims' list. Got: %s. "
            "Fix: regenerate the provisioning artifact.",
            action_spec,
        )
        sys.exit(1)

    script = _build_token_claim_script(name, claims)

    existing = _list_actions(api)
    action_id: str | None = None
    for action in existing:
        if action.get("name") == name:
            candidate = action.get("id")
            if isinstance(candidate, str) and candidate:
                action_id = candidate
            break

    if action_id is not None:
        logger.info("action_exists name=%s id=%s", name, action_id)
        _update_action(api, action_id, name, script)
    else:
        action_id = _create_action(api, name, script)

    for trigger_type in _TRIGGER_TYPES_TOKEN_CLAIM:
        _set_trigger_actions(
            api, _FLOW_TYPE_COMPLEMENT_TOKEN, trigger_type, [action_id]
        )


# ---------------------------------------------------------------------------
# Login policy (self-registration)
# ---------------------------------------------------------------------------

#: The scalar fields of the org login policy that GET returns and POST/PUT accept
#: (Zitadel Management API v1, ``GetLoginPolicy`` / ``AddCustomLoginPolicy`` /
#: ``UpdateCustomLoginPolicy``). A write carries ALL of them, copied from the policy
#: in force: the API documents no partial update, so a write naming only
#: ``allowRegister`` would risk resetting ``allowUsernamePassword`` and turning
#: password sign-in off.
_LOGIN_POLICY_SCALAR_FIELDS: tuple[str, ...] = (
    "allowUsernamePassword",
    "allowRegister",
    "allowExternalIdp",
    "forceMfa",
    "passwordlessType",
    "hidePasswordReset",
    "ignoreUnknownUsernames",
    "defaultRedirectUri",
    "passwordCheckLifetime",
    "externalLoginCheckLifetime",
    "mfaInitSkipLifetime",
    "secondFactorCheckLifetime",
    "multiFactorCheckLifetime",
    "allowDomainDiscovery",
    "disableLoginWithEmail",
    "disableLoginWithPhone",
    "forceMfaLocalOnly",
)

#: Fields only the create call (``AddCustomLoginPolicy``) accepts; the update call
#: leaves the factor lists to their own endpoints.
_LOGIN_POLICY_CREATE_ONLY_FIELDS: tuple[str, ...] = ("secondFactors", "multiFactors")


def _get_login_policy(api: _Api) -> tuple[dict[str, object], bool]:
    """Read the login policy in force for the org (GET /policies/login).

    Returns:
        ``(policy, is_default)`` -- the policy object and whether the org has no
        policy of its own, so the instance default applies.

    Raises:
        SystemExit(1): On API error or a response without a ``policy`` object.
    """
    status, body = _json_request(api.mgmt_base + "/policies/login", api)
    policy = body.get("policy")
    if status != 200 or not isinstance(policy, dict):
        logger.error(
            "Failed to read the login policy (HTTP %d): %s. "
            "Fix: verify the machine-user PAT has org-level permissions.",
            status,
            body,
        )
        sys.exit(1)
    is_default = bool(body.get("isDefault", policy.get("isDefault", False)))
    return policy, is_default


def _login_policy_payload(
    policy: dict[str, object], desired: Mapping[str, bool], *, creating: bool
) -> dict[str, object]:
    """Copy the policy in force and set the *desired* settings.

    Args:
        policy: The policy object GET returned.
        desired: The settings to set, by name.
        creating: ``True`` for the create call, which also carries the factor lists.
    """
    fields = _LOGIN_POLICY_SCALAR_FIELDS + (
        _LOGIN_POLICY_CREATE_ONLY_FIELDS if creating else ()
    )
    payload: dict[str, object] = {name: policy[name] for name in fields if name in policy}
    payload.update(desired)
    return payload


def _converge_login_policy(
    api: _Api, desired: Mapping[str, bool], *, require_custom: bool = False
) -> None:
    """Idempotently converge boolean settings of the org login policy.

    Reads the policy in force. When it already has every desired value nothing is
    written, unless *require_custom* asks for the org's own policy and the org is still on
    the instance default. An org on the instance default gets a custom policy (POST)
    copied from that default; an org with its own policy is updated (PUT). Every other
    login setting is carried over unchanged.

    Args:
        api: Connection context.
        desired: The settings to hold, by name.
        require_custom: The org must hold a policy of its own afterwards.

    Raises:
        SystemExit(1): When any API call fails.
    """
    policy, is_default = _get_login_policy(api)
    # Zitadel's REST gateway writes proto3 JSON, which omits a boolean that is
    # ``false``: a closed policy comes back without ``allowRegister`` at all.
    held = all(policy.get(name, False) is value for name, value in desired.items())
    if held and not (require_custom and is_default):
        logger.info("login_policy_converged %s", dict(desired))
        return
    method = "POST" if is_default else "PUT"
    payload = _login_policy_payload(policy, desired, creating=is_default)
    status, body = _json_request(
        api.mgmt_base + "/policies/login", api, method=method, payload=payload
    )
    if status not in (200, 201) and not _is_no_changes(status, body):
        logger.error(
            "Failed to set the login policy %s (%s, HTTP %d): %s.",
            dict(desired),
            method,
            status,
            body,
        )
        sys.exit(1)
    logger.info("login_policy_set %s method=%s", dict(desired), method)


#: The org login-policy settings an artifact ``loginPolicy`` block may declare, all booleans.
_LOGIN_POLICY_SPEC_FIELDS: tuple[str, ...] = ("allowRegister", "forceMfa", "forceMfaLocalOnly")


def _ensure_login_policy(
    api: _Api, spec: dict[str, object], *, require_custom: bool = False
) -> None:
    """Idempotently converge the org login policy's declared settings.

    Args:
        api: Connection context.
        spec: The artifact ``loginPolicy`` block: a non-empty object of the boolean
            settings in ``_LOGIN_POLICY_SPEC_FIELDS`` (``allowRegister``, ``forceMfa``,
            ``forceMfaLocalOnly``).
        require_custom: The org must hold a policy of its own afterwards (an org the
            applier created, whose second-factor policy must not be the instance
            default's).

    Raises:
        SystemExit(1): When the spec is empty, names an unknown setting or a non-boolean
            value, or any API call fails.
    """
    unknown = sorted(set(spec) - set(_LOGIN_POLICY_SPEC_FIELDS))
    desired = {name: spec[name] for name in _LOGIN_POLICY_SPEC_FIELDS if name in spec}
    if unknown or not desired or not all(isinstance(v, bool) for v in desired.values()):
        logger.error(
            "loginPolicy must be a non-empty object of boolean settings from %s. Got: %s. "
            "Fix: regenerate the provisioning artifact.",
            list(_LOGIN_POLICY_SPEC_FIELDS),
            spec,
        )
        sys.exit(1)
    _converge_login_policy(
        api, {name: bool(value) for name, value in desired.items()}, require_custom=require_custom
    )


#: ``POST`` adds an identity provider to the org login policy, which is what lists it on
#: the hosted login page (Management API ``AddIDPToLoginPolicy``).
_LOGIN_POLICY_IDPS_PATH: str = "/policies/login/idps"
_IDP_OWNER_TYPE_ORG: str = "IDP_OWNER_TYPE_ORG"


def _link_social_idps_to_login_policy(api: _Api, idp_ids: list[str]) -> None:
    """List each social IdP on the hosted login page.

    An IdP exists in the instance without appearing on the login page until the org's login
    policy names it, and an org on the instance default has no policy of its own to name it
    in. So the org gets its own policy first, with external IdPs allowed, then each IdP is
    added to it. An IdP already on the policy answers 409 and is converged.

    Args:
        api: Connection context.
        idp_ids: The ids of the org's social IdPs; none means nothing is touched.

    Raises:
        SystemExit(1): When any API call fails.
    """
    if not idp_ids:
        return
    _converge_login_policy(api, {"allowExternalIdp": True}, require_custom=True)
    for idp_id in idp_ids:
        status, body = _json_request(
            api.mgmt_base + _LOGIN_POLICY_IDPS_PATH,
            api,
            method="POST",
            payload={"idpId": idp_id, "ownerType": _IDP_OWNER_TYPE_ORG},
        )
        if status not in (200, 201, 409):
            logger.error(
                "Failed to list social IdP id=%s on the login policy (HTTP %d): %s. "
                "Fix: verify the machine-user PAT has org-level permissions.",
                idp_id,
                status,
                body,
            )
            sys.exit(1)
        logger.info("social_idp_listed idpId=%s status=%d", idp_id, status)


def _apply_login_policy(
    api: _Api, login_policy: object, *, require_custom: bool = False
) -> None:
    """Converge the org login policy when the artifact declares one.

    Absent when no provisioned provider declares ``signUp``: the instance policy
    is then left exactly as Zitadel has it.

    Raises:
        SystemExit(1): The artifact's ``loginPolicy`` is not an object.
    """
    if login_policy is None:
        logger.info("login_policy_skipped reason=no_provider_declares_sign_up")
        return
    if not isinstance(login_policy, dict):
        logger.error(
            "Provisioning artifact 'loginPolicy' must be an object. Got: %s. "
            "Fix: regenerate the provisioning artifact.",
            login_policy,
        )
        sys.exit(1)
    _ensure_login_policy(api, login_policy, require_custom=require_custom)


#: The Admin API base, beside the Management API on the same instance: the instance's own
#: settings live there, among them the OIDC token lifetimes.
_ADMIN_BASE: str = "/admin/v1"
_OIDC_SETTINGS_PATH: str = "/settings/oidc"

#: Every duration field of the instance OIDC settings. An update carries all of them, each
#: one the artifact does not set copied from what the instance holds.
_OIDC_SETTINGS_FIELDS: tuple[str, ...] = (
    "accessTokenLifetime",
    "idTokenLifetime",
    "refreshTokenIdleExpiration",
    "refreshTokenExpiration",
)
_REFRESH_IDLE_FIELD: str = "refreshTokenIdleExpiration"
_REFRESH_EXPIRATION_FIELD: str = "refreshTokenExpiration"

#: A protobuf JSON duration: whole or fractional seconds with an ``s`` suffix.
_PROTO_DURATION = re.compile(r"^\d+(?:\.\d+)?s$")


def _admin_url(api: _Api, path: str) -> str:
    """*path* under the Admin API of the instance *api* addresses."""
    return api.mgmt_base.removesuffix(_MANAGEMENT_BASE) + _ADMIN_BASE + path


def _duration_seconds(value: object) -> float | None:
    """The seconds of a protobuf JSON duration (``"3600s"``), or ``None`` when *value* is none."""
    if isinstance(value, str) and _PROTO_DURATION.match(value):
        return float(value[:-1])
    return None


def _require_oidc_settings_spec(oidc_settings: object) -> dict[str, str]:
    """The artifact's ``oidcSettings``: known fields, each a protobuf JSON duration.

    Raises:
        SystemExit(1): The block is not such an object.
    """
    if (
        isinstance(oidc_settings, dict)
        and oidc_settings
        and all(name in _OIDC_SETTINGS_FIELDS for name in oidc_settings)
        and all(_duration_seconds(value) is not None for value in oidc_settings.values())
    ):
        return {str(name): str(value) for name, value in oidc_settings.items()}
    logger.error(
        "Provisioning artifact 'oidcSettings' must be an object of durations such as "
        "{\"accessTokenLifetime\": \"3600s\"} over the fields %s. Got: %s. "
        "Fix: regenerate the provisioning artifact.",
        list(_OIDC_SETTINGS_FIELDS),
        oidc_settings,
    )
    sys.exit(1)


def _get_oidc_settings(api: _Api) -> dict[str, object]:
    """The instance OIDC settings in force (Admin API ``GET /settings/oidc``).

    Raises:
        SystemExit(1): On API error or a response without a ``settings`` object.
    """
    status, body = _json_request(_admin_url(api, _OIDC_SETTINGS_PATH), api)
    settings = body.get("settings")
    if status != 200 or not isinstance(settings, dict):
        logger.error(
            "Failed to read the instance OIDC settings (HTTP %d): %s. "
            "Fix: verify the machine-user PAT holds IAM_OWNER on the instance.",
            status,
            body,
        )
        sys.exit(1)
    return settings


def _apply_oidc_settings(api: _Api, oidc_settings: object) -> None:
    """Converge the instance's OIDC token lifetimes to the artifact's ``oidcSettings``.

    Absent when no provisioned provider states a token lifetime: the instance then keeps
    Zitadel's own. Otherwise the settings in force are read, the stated lifetimes replace
    theirs, and an idle refresh expiration longer than the refresh token's own lifetime is
    cut to it. Nothing is written when every lifetime already holds.

    Raises:
        SystemExit(1): The block is malformed, or an API call fails.
    """
    if oidc_settings is None:
        logger.info("oidc_settings_skipped reason=no_provider_states_a_token_lifetime")
        return
    spec = _require_oidc_settings_spec(oidc_settings)
    held = _get_oidc_settings(api)
    desired: dict[str, object] = {name: held.get(name) for name in _OIDC_SETTINGS_FIELDS}
    desired.update(spec)
    refresh = _duration_seconds(desired.get(_REFRESH_EXPIRATION_FIELD))
    idle = _duration_seconds(desired.get(_REFRESH_IDLE_FIELD))
    if refresh is not None and (idle is None or idle > refresh):
        desired[_REFRESH_IDLE_FIELD] = desired[_REFRESH_EXPIRATION_FIELD]
    payload = {name: value for name, value in desired.items() if value is not None}
    if all(
        _duration_seconds(held.get(name)) == _duration_seconds(value)
        for name, value in payload.items()
    ):
        logger.info("oidc_settings_converged %s", payload)
        return
    status, body = _json_request(
        _admin_url(api, _OIDC_SETTINGS_PATH), api, method="PUT", payload=payload
    )
    if status not in (200, 201) and not _is_no_changes(status, body):
        logger.error(
            "Failed to set the instance OIDC settings %s (HTTP %d): %s. "
            "Fix: verify the machine-user PAT holds IAM_OWNER on the instance.",
            payload,
            status,
            body,
        )
        sys.exit(1)
    logger.info("oidc_settings_set %s", payload)


# ---------------------------------------------------------------------------
# The instance's own mail provider
# ---------------------------------------------------------------------------
#
# Zitadel mails what it issues itself (the invitation code, a password reset, an email
# verification) through the instance's one active email provider. The applier converges it
# through the Admin API on every run, so an instance created before the provider was
# declared, or one whose mail settings changed since, gets it as well.
#
# Zitadel v3.0.0 stores no password for a provider added or changed with an empty one, and
# its notification worker then reports ``Errors.SMTPConfig.NotFound`` for an active provider
# (``internal/notification/handlers/config_email.go``, ``QUERY-Wrs3gw``). It logs in only
# when both the user and the password are set (``channels/smtp/config.go``, ``HasAuth``).
# A relay that takes no login is therefore given an empty user and a random password, which
# is stored but never sent.

_EMAIL_PROVIDERS_PATH: str = "/email"
_DOMAIN_POLICY_PATH: str = "/policies/domain"
_EMAIL_PROVIDER_ACTIVE: str = "EMAIL_PROVIDER_ACTIVE"
#: The domain-policy fields an update must carry; this step changes only the last.
_DOMAIN_POLICY_FIELDS: tuple[str, ...] = (
    "userLoginMustBeDomain",
    "validateOrgDomains",
    "smtpSenderAddressMatchesInstanceDomain",
)
_SENDER_DOMAIN_MATCH_FIELD: str = "smtpSenderAddressMatchesInstanceDomain"
#: How long a provider just activated may take to be the one the instance reports active.
_MAIL_PROVIDER_READ_BACK_SECONDS: float = 30.0
_MAIL_PROVIDER_READ_BACK_POLL_SECONDS: float = 1.0
#: The length of a password the applier makes: Mailgun takes 5 to 32 characters.
_GENERATED_PASSWORD_LENGTH: int = 32


class _MailgunLogin(NamedTuple):
    """The Mailgun SMTP login the applier keeps on the services' sending domain."""

    api_base: str
    api_key_ref: str
    domain_ref: str
    login: str


class _SmtpEndpoint(NamedTuple):
    """Where the instance sends, and how it logs in: a fixed user with a password secret, a
    Mailgun login the applier keeps, or no login at all (both references ``None``)."""

    host: str
    tls: bool
    user: str
    password_ref: str | None
    mailgun: _MailgunLogin | None


class _MailProvider(NamedTuple):
    """The artifact's ``mailProvider``."""

    description: str
    sender_address: str
    sender_name: str
    lift_sender_domain_match: bool
    smtp: _SmtpEndpoint


def _text(block: Mapping[str, object], name: str) -> str | None:
    """*block*'s non-empty string *name*, or ``None``."""
    value = block.get(name)
    return value if isinstance(value, str) and value else None


def _mailgun_login(block: object) -> _MailgunLogin | None:
    """The ``mailgunCredential`` of an smtp block, or ``None`` when it names none."""
    if not isinstance(block, dict):
        return None
    fields = [_text(block, name) for name in ("apiBase", "apiKeyRef", "domainRef", "login")]
    if any(field is None for field in fields):
        return None
    return _MailgunLogin(*(str(field) for field in fields))


def _smtp_endpoint(block: object) -> _SmtpEndpoint | None:
    """The smtp block of a ``mailProvider``, or ``None`` when it is malformed."""
    if not isinstance(block, dict):
        return None
    host = _text(block, "host")
    tls = block.get("tls")
    user = block.get("user", "")
    if host is None or not isinstance(tls, bool) or not isinstance(user, str):
        return None
    mailgun = block.get("mailgunCredential")
    login = _mailgun_login(mailgun)
    if mailgun is not None and login is None:
        return None
    return _SmtpEndpoint(host, tls, user, _text(block, "passwordRef"), login)


def _require_mail_provider(spec: object) -> _MailProvider:
    """The artifact's ``mailProvider``: a sender and the SMTP endpoint it sends through.

    Raises:
        SystemExit(1): The block is not such an object.
    """
    if isinstance(spec, dict):
        texts = [_text(spec, name) for name in ("description", "senderAddress", "senderName")]
        lift = spec.get("liftSenderDomainMatch")
        smtp = _smtp_endpoint(spec.get("smtp"))
        if all(text is not None for text in texts) and isinstance(lift, bool) and smtp is not None:
            return _MailProvider(str(texts[0]), str(texts[1]), str(texts[2]), lift, smtp)
    logger.error(
        "Provisioning artifact 'mailProvider' must name a description, senderAddress, "
        "senderName, liftSenderDomainMatch and an smtp endpoint (host, tls, and a "
        "passwordRef or mailgunCredential when it takes a login). Got: %s. "
        "Fix: regenerate the provisioning artifact.",
        spec,
    )
    sys.exit(1)


def _converge_sender_domain_policy(api: _Api, lift: bool) -> None:
    """Let the instance send from a domain other than its own when the sender needs it.

    Zitadel refuses a provider whose sender is outside the instance's domain while the
    instance's domain policy requires the match; the policy is read, and written only when
    the sender needs the match lifted and it is not.

    Raises:
        SystemExit(1): An API call fails.
    """
    if not lift:
        return
    status, body = _json_request(_admin_url(api, _DOMAIN_POLICY_PATH), api)
    policy = body.get("policy")
    if status != 200 or not isinstance(policy, dict):
        logger.error(
            "Failed to read the instance domain policy (HTTP %d): %s. "
            "Fix: verify the machine-user PAT holds IAM_OWNER on the instance.",
            status,
            body,
        )
        sys.exit(1)
    # Zitadel's REST gateway writes proto3 JSON, which omits a boolean that is ``false``: a
    # policy that already lets the instance send from any domain comes back without the field.
    if policy.get(_SENDER_DOMAIN_MATCH_FIELD, False) is False:
        return
    payload: dict[str, object] = {name: bool(policy.get(name, False)) for name in _DOMAIN_POLICY_FIELDS}
    payload[_SENDER_DOMAIN_MATCH_FIELD] = False
    status, body = _json_request(
        _admin_url(api, _DOMAIN_POLICY_PATH), api, method="PUT", payload=payload
    )
    if status not in (200, 201) and not _is_no_changes(status, body):
        logger.error(
            "Failed to let the instance send from the declared sender's domain (HTTP %d): %s. "
            "Fix: verify the machine-user PAT holds IAM_OWNER on the instance.",
            status,
            body,
        )
        sys.exit(1)
    logger.info("sender_domain_match_lifted")


def _mailgun_form(url: str, api_key: str, method: str, fields: Mapping[str, str]) -> int:
    """Send *fields* form-encoded to Mailgun's *url*, authenticated with *api_key*; the status.

    Raises:
        SystemExit(1): The URL is not https, or Mailgun cannot be reached.
    """
    if not url.startswith("https://"):
        logger.error("The Mailgun API base must be https; got '%s'. Fix: regenerate.", url)
        sys.exit(1)
    credentials = base64.b64encode(("api:%s" % api_key).encode("utf-8")).decode("ascii")
    req = urllib.request.Request(
        url,
        data=urllib.parse.urlencode(dict(fields)).encode("utf-8"),
        headers={"Authorization": "Basic %s" % credentials},
        method=method,
    )
    try:
        # The URL is the https Mailgun API base checked above.
        with urllib.request.urlopen(req, timeout=_REQUEST_TIMEOUT_SECONDS) as resp:  # nosec B310
            return int(resp.status)
    except urllib.error.HTTPError as exc:
        return int(exc.code)
    except (urllib.error.URLError, TimeoutError) as exc:
        logger.error(
            "Network error calling Mailgun '%s %s': %s. "
            "Fix: let the init container reach the Mailgun API.",
            method,
            url,
            getattr(exc, "reason", exc),
        )
        sys.exit(1)


def _mailgun_password(login: _MailgunLogin) -> tuple[str, str]:
    """Set a fresh password on the Mailgun SMTP login the instance sends as, creating the
    login on first use, and return ``(user, password)``.

    The services hold Mailgun's API key and sending domain; an SMTP login is a separate
    Mailgun credential, so the applier keeps one of its own on that domain.

    Raises:
        SystemExit(1): A reference is unresolvable or Mailgun refuses the credential.
    """
    api_key = _resolve_secret_ref(login.api_key_ref, "The mail provider's Mailgun API key")
    domain = _resolve_secret_ref(login.domain_ref, "The mail provider's Mailgun domain")
    password = secrets.token_urlsafe(_GENERATED_PASSWORD_LENGTH)[:_GENERATED_PASSWORD_LENGTH]
    base = "%s/v3/domains/%s/credentials" % (login.api_base.rstrip("/"), urllib.parse.quote(domain, safe=""))
    status = _mailgun_form(
        base + "/" + urllib.parse.quote(login.login, safe=""), api_key, "PUT", {"password": password}
    )
    if status == 404:
        status = _mailgun_form(base, api_key, "POST", {"login": login.login, "password": password})
    if status not in (200, 201):
        logger.error(
            "Mailgun refused the SMTP login '%s' on the sending domain (HTTP %d). "
            "Fix: verify the services' Mailgun API key may manage that domain's SMTP credentials.",
            login.login,
            status,
        )
        sys.exit(1)
    return "%s@%s" % (login.login, domain), password


def _smtp_login(smtp: _SmtpEndpoint) -> tuple[str, str]:
    """The ``(user, password)`` the instance logs in to its SMTP endpoint with.

    Raises:
        SystemExit(1): A secret reference cannot be resolved.
    """
    if smtp.mailgun is not None:
        return _mailgun_password(smtp.mailgun)
    if smtp.password_ref is not None:
        return smtp.user, _resolve_secret_ref(smtp.password_ref, "The mail provider's SMTP password")
    # A relay that takes no login: an empty user, so Zitadel never logs in, and a password,
    # so Zitadel stores the provider as usable (section comment above).
    return "", secrets.token_urlsafe(_GENERATED_PASSWORD_LENGTH)


def _list_email_providers(api: _Api) -> list[dict[str, object]]:
    """Every email provider of the instance.

    Raises:
        SystemExit(1): The list call fails.
    """
    status, body = _json_request(
        _admin_url(api, _EMAIL_PROVIDERS_PATH + "/_search"), api, method="POST", payload={}
    )
    if status != 200:
        logger.error(
            "Failed to list the instance email providers (HTTP %d): %s. "
            "Fix: verify the machine-user PAT holds IAM_OWNER on the instance.",
            status,
            body,
        )
        sys.exit(1)
    result = body.get("result")
    return [entry for entry in result if isinstance(entry, dict)] if isinstance(result, list) else []


def _ensure_smtp_provider(api: _Api, spec: _MailProvider) -> tuple[str, bool]:
    """Add the instance's SMTP provider, or update the one this applier added; its id and
    whether it is already the active one.

    Raises:
        SystemExit(1): An API call fails.
    """
    user, password = _smtp_login(spec.smtp)
    payload: dict[str, object] = {
        "senderAddress": spec.sender_address,
        "senderName": spec.sender_name,
        "tls": spec.smtp.tls,
        "host": spec.smtp.host,
        "user": user,
        "password": password,
        "description": spec.description,
    }
    held = [entry for entry in _list_email_providers(api) if entry.get("description") == spec.description]
    if not held:
        status, body = _json_request(
            _admin_url(api, _EMAIL_PROVIDERS_PATH + "/smtp"), api, method="POST", payload=payload
        )
        provider_id = body.get("id")
        if status not in (200, 201) or not isinstance(provider_id, str) or not provider_id:
            logger.error(
                "Failed to add the instance SMTP provider '%s' (HTTP %d): %s. "
                "Fix: verify the sender address and host.",
                spec.smtp.host,
                status,
                body,
            )
            sys.exit(1)
        logger.info("mail_provider_added id=%s host=%s", provider_id, spec.smtp.host)
        return provider_id, False
    provider_id = str(held[0].get("id", ""))
    path = "%s/smtp/%s" % (_EMAIL_PROVIDERS_PATH, urllib.parse.quote(provider_id, safe=""))
    status, body = _json_request(_admin_url(api, path), api, method="PUT", payload=payload)
    if status not in (200, 201) and not _is_no_changes(status, body):
        logger.error(
            "Failed to update the instance SMTP provider %s (HTTP %d): %s. "
            "Fix: verify the sender address and host.",
            provider_id,
            status,
            body,
        )
        sys.exit(1)
    logger.info("mail_provider_updated id=%s host=%s", provider_id, spec.smtp.host)
    return provider_id, held[0].get("state") == _EMAIL_PROVIDER_ACTIVE


def _active_email_provider_id(api: _Api) -> str | None:
    """The id of the provider the instance sends with, or ``None`` when it has none."""
    status, body = _json_request(_admin_url(api, _EMAIL_PROVIDERS_PATH), api)
    config = body.get("config")
    if status == 200 and isinstance(config, dict) and isinstance(config.get("id"), str):
        return str(config["id"])
    return None


def _require_mail_provider_reported(api: _Api, provider_id: str) -> None:
    """Wait until the instance reports *provider_id* as the provider it sends with.

    Raises:
        SystemExit(1): It does not within the read-back deadline -- an instance that would
            not mail through the declared provider.
    """
    deadline = time.monotonic() + _MAIL_PROVIDER_READ_BACK_SECONDS
    active = _active_email_provider_id(api)
    while active != provider_id:
        if time.monotonic() >= deadline:
            logger.error(
                "The instance still sends with email provider %s, not %s, %ss after it was "
                "activated, so the mail it issues (invitations, resets) would not go through "
                "the declared provider. Fix: check the Zitadel server logs.",
                active,
                provider_id,
                _MAIL_PROVIDER_READ_BACK_SECONDS,
            )
            sys.exit(1)
        time.sleep(_MAIL_PROVIDER_READ_BACK_POLL_SECONDS)
        active = _active_email_provider_id(api)
    logger.info("mail_provider_active id=%s", provider_id)


def _activate_email_provider(api: _Api, provider_id: str) -> None:
    """Make *provider_id* the provider the instance sends with.

    Raises:
        SystemExit(1): The activation fails.
    """
    path = "%s/%s/_activate" % (_EMAIL_PROVIDERS_PATH, urllib.parse.quote(provider_id, safe=""))
    status, body = _json_request(_admin_url(api, path), api, method="POST", payload={})
    if status not in (200, 201):
        logger.error(
            "Failed to activate the instance email provider %s (HTTP %d): %s. "
            "Fix: verify the machine-user PAT holds IAM_OWNER on the instance.",
            provider_id,
            status,
            body,
        )
        sys.exit(1)


def _apply_mail_provider(api: _Api, mail_provider: object) -> None:
    """Converge the instance's own email provider to the artifact's ``mailProvider``.

    Absent when no service declares email: the instance then mails nothing of its own.
    Otherwise the provider is added or updated, activated when it is not the active one,
    and read back until the instance reports it.

    Raises:
        SystemExit(1): The block is malformed, an API call fails, or the read-back fails.
    """
    if mail_provider is None:
        logger.info("mail_provider_skipped reason=no_email_declared")
        return
    spec = _require_mail_provider(mail_provider)
    _converge_sender_domain_policy(api, spec.lift_sender_domain_match)
    provider_id, active = _ensure_smtp_provider(api, spec)
    if not active:
        _activate_email_provider(api, provider_id)
    _require_mail_provider_reported(api, provider_id)


# ---------------------------------------------------------------------------
# Main orchestration
# ---------------------------------------------------------------------------


def _validate_project(project: dict[str, Any]) -> None:
    """Validate that a project entry has the required 'name' field.

    Args:
        project: Project dict from the artifact.

    Raises:
        SystemExit(1): When 'name' is absent or empty.
    """
    name = project.get("name")
    if not isinstance(name, str) or not name:
        logger.error(
            "Project entry in artifact is missing required 'name' field. "
            "Got: %s. Fix: regenerate the provisioning artifact.",
            project,
        )
        sys.exit(1)


def _load_provider_plan(plan_path: str) -> dict[str, Any]:
    """Read a provider plan file: the generated template or the deployed plan.

    Raises:
        SystemExit(1): The plan is missing or is not valid JSON.
    """
    if not os.path.exists(plan_path):
        logger.error(
            "Provider plan not found at '%s'. "
            "Fix: regenerate the project with cruftfree and verify the init-job mounts "
            "'config/identity/identity-providers.template.json' at "
            "IDENTITY_PROVIDER_PLAN_TEMPLATE_FILE and "
            "'config/identity/identity-providers.json' read-write at "
            "IDENTITY_PROVIDER_PLAN_FILE.",
            plan_path,
        )
        sys.exit(1)
    try:
        with open(plan_path, "r", encoding="utf-8") as fh:
            plan: dict[str, Any] = json.load(fh)
    except json.JSONDecodeError as exc:
        logger.error(
            "Provider plan at '%s' is not valid JSON: %s. "
            "Fix: regenerate the plan with cruftfree.",
            plan_path,
            exc,
        )
        sys.exit(1)
    return plan


def _is_project_audience_sentinel(audience: object) -> bool:
    """True for a ``zitadel-project-audience:<projectName>`` sentinel."""
    return isinstance(audience, str) and audience.startswith(
        _PROJECT_AUDIENCE_SENTINEL_PREFIX
    )


def _resolve_audience(
    provider_name: str, audience: object, project_ids: dict[str, str]
) -> object:
    """*audience* with a project sentinel replaced by the project's assigned ID.

    Raises:
        SystemExit(1): The sentinel names a project that was not provisioned.
    """
    if not isinstance(audience, str) or not _is_project_audience_sentinel(audience):
        return audience
    project_name = audience[len(_PROJECT_AUDIENCE_SENTINEL_PREFIX):]
    project_id = project_ids.get(project_name)
    if not project_id:
        logger.error(
            "Provider '%s' allowedAudiences references project '%s' that "
            "was not provisioned. Provisioned projects: %s. "
            "Fix: ensure the provisioning artifact creates a project named "
            "'%s' (the planner derives the sentinel and the artifact "
            "project name from the same zitadelIdentity config).",
            provider_name,
            project_name,
            sorted(project_ids),
            project_name,
        )
        sys.exit(1)
    return project_id


def _plan_providers(plan: dict[str, object], plan_path: str) -> dict[str, object]:
    """The ``providers`` object of the plan read from *plan_path*.

    Raises:
        SystemExit(1): The plan carries no ``providers`` object.
    """
    providers = plan.get("providers")
    if not isinstance(providers, dict):
        logger.error(
            "Provider plan at '%s' carries no 'providers' object. Got: %s. "
            "Fix: regenerate the plan with cruftfree.",
            plan_path,
            type(providers).__name__,
        )
        sys.exit(1)
    return providers


def _render_provider_plan(
    template_path: str,
    plan_path: str,
    project_ids: dict[str, str],
) -> None:
    """Render the deployed provider plan from its template, resolving audiences.

    The generated plan emits each CruftFree-provisioned Zitadel provider's
    ``allowedAudiences`` as a ``zitadel-project-audience:<projectName>`` sentinel,
    because the project ID is assigned by Zitadel only at provisioning time.  This
    replaces each sentinel with the matching project's assigned ID so the backend
    validators (which check the token ``aud`` against ``allowedAudiences``) accept
    the project ID Zitadel actually mints into access tokens.

    The sentinels are read from the template, which no deploy writes, and never
    from the deployed plan: a fresh Zitadel (a ``docker compose down -v``) assigns
    new project IDs, and a previous run's resolved plan has no sentinel left to
    resolve them from.

    The plan file is written **in place** (same inode) so the read-only mount the
    backend services share keeps pointing at the rendered content.  Backend
    services depend on this init-job completing, so they never read a half-written
    plan.

    Args:
        template_path: Filesystem path to the read-only
            ``identity-providers.template.json``.
        plan_path: Filesystem path to the writable ``identity-providers.json``.
        project_ids: Map of Zitadel project name -> assigned project ID, built
            while provisioning projects.

    Raises:
        SystemExit(1): When the template is missing/invalid, or a sentinel
            references a project that was not provisioned (so its ID is unknown).
    """
    plan = _load_provider_plan(template_path)
    resolved = 0
    for provider_name, entry in _plan_providers(plan, template_path).items():
        if not isinstance(entry, dict):
            continue
        audiences = entry.get("allowedAudiences")
        if not isinstance(audiences, list):
            continue
        if not any(_is_project_audience_sentinel(aud) for aud in audiences):
            continue
        new_audiences = [
            _resolve_audience(provider_name, aud, project_ids) for aud in audiences
        ]
        entry["allowedAudiences"] = new_audiences
        resolved += 1
        logger.info(
            "provider_plan_audience_resolved provider=%s audiences=%s",
            provider_name,
            new_audiences,
        )

    with open(plan_path, "w", encoding="utf-8") as fh:
        json.dump(plan, fh, sort_keys=True)
    logger.info("provider_plan_rendered path=%s resolved=%d", plan_path, resolved)


def _require_machine_audience_accepted(plan_path: str, credentials_path: str) -> None:
    """Exit non-zero unless the deployed plan accepts the machine credentials' audience.

    Nothing makes a peer call while the stack starts, so a plan and credentials
    that name different projects pass every health check and then answer every
    service-to-service call 401.  Both sides are read back from the files the
    services mount.  A provider with no ``allowedAudiences`` does not count: it is
    not constraining the audience, and it is not what verifies these tokens.

    Args:
        plan_path: Filesystem path to the rendered ``identity-providers.json``.
        credentials_path: Filesystem path to the written machine credentials.

    Raises:
        SystemExit(1): No provider in the plan accepts the machine audience.
    """
    with open(credentials_path, "r", encoding="utf-8") as fh:
        machine_audience = json.load(fh).get("audience")
    accepted_project_ids: set[str] = set()
    for entry in _plan_providers(_load_provider_plan(plan_path), plan_path).values():
        audiences = entry.get("allowedAudiences") if isinstance(entry, dict) else None
        if isinstance(audiences, list):
            accepted_project_ids.update(aud for aud in audiences if isinstance(aud, str))
    if machine_audience in {_machine_audience_scope(p) for p in accepted_project_ids}:
        logger.info("machine_audience_accepted audience=%s", machine_audience)
        return
    logger.error(
        "The machine credentials at '%s' request audience '%s', which no provider in "
        "the deployed plan at '%s' accepts (allowedAudiences: %s). Every "
        "service-to-service call would answer 401 audience_mismatch. Expected: the "
        "machine project's ID in the allowedAudiences of its provider. "
        "Fix: regenerate the project with cruftfree and deploy again.",
        credentials_path,
        machine_audience,
        plan_path,
        sorted(accepted_project_ids),
    )
    sys.exit(1)


#: URL schemes a Management API base may use. ``urllib.request.urlopen`` also opens
#: ``file:`` and ``ftp:`` URLs, so a base URL outside this set is refused before the
#: bearer token is attached to any request.
_ALLOWED_URL_SCHEMES: frozenset[str] = frozenset({"http", "https"})


def _require_http_base_url(instance_url: str) -> None:
    """Exit non-zero unless *instance_url* is an ``http``/``https`` URL with a host."""
    parts = urllib.parse.urlsplit(instance_url)
    if parts.scheme.lower() in _ALLOWED_URL_SCHEMES and parts.hostname:
        return
    logger.error(
        "ZITADEL_INSTANCE_URL '%s' is not an http(s) URL with a host. "
        "Expected: scheme http or https plus the internal Zitadel host[:port], "
        "e.g. http://zitadel:8080. "
        "Fix: set ZITADEL_INSTANCE_URL on the init container to the Zitadel service URL.",
        instance_url,
    )
    sys.exit(1)


def apply_provisioning(
    instance_url: str,
    host_header: str,
    token: str,
    provisioning_path: str,
) -> "_Provisioned":
    """Read the provisioning artifact and apply all resources via Zitadel Management API.

    Applies in order: Projects -> project Roles -> OIDC Apps -> machine user ->
    social IdPs, then the org-level Complement-Token claim-injection action, the
    org login policy and the instance OIDC token lifetimes (each when the artifact declares
    one).  A project that declares an ``organization`` is applied inside an organization
    of its own (created when absent) with that organization's own login policy, social
    IdP listing and claim-injection action, and its ``introspectionClient`` key is
    written for the services; every other project is applied in the default organization.
    Every operation is idempotent via explicit
    get-before-create/update.  Partial failures exit non-zero immediately — no
    best-effort continuation.

    Args:
        instance_url: Internal Zitadel base URL (scheme+host+port).
        host_header: Instance external domain[:port] sent as the HTTP Host header.
        token: Bearer token (the FIRSTINSTANCE machine-user PAT).
        provisioning_path: Filesystem path to the provisioning artifact.

    Returns:
        A :class:`_Provisioned`: ``project_ids`` maps Zitadel
        project name -> assigned project ID (used to resolve the provider plan's
        ``allowedAudiences`` sentinels); ``machine_credentials`` is the inter-
        service machine credential material (``clientId``/``clientSecret``/
        ``audience``), or ``None`` when no project declares a ``machineUser``;
        ``organization_ids`` maps each provider provisioned into an organization of its own
        to that organization's id.
    """
    _require_http_base_url(instance_url)
    base = instance_url.rstrip("/")
    api = _Api(
        mgmt_base=base + _MANAGEMENT_BASE,
        token=token,
        host_header=host_header,
    )

    logger.info(
        "zitadel_applier_start instance=%s host=%s artifact=%s",
        base,
        host_header,
        provisioning_path,
    )

    artifact = _load_artifact(provisioning_path)
    _wait_for_management_api(api)

    projects: list[dict[str, Any]] = artifact["projects"]
    logger.info("provisioning_projects count=%d", len(projects))

    project_ids: dict[str, str] = {}
    machine_credentials: dict[str, str] | None = None
    social_idp_ids: list[str] = []
    organization_ids: dict[str, str] = {}
    for project in projects:
        organization = project.get("organization")
        project_api = api
        organization_id = ""
        if organization is not None:
            organization_id = _ensure_organization(
                api, _require_organization_block(project, organization)
            )
            project_api = api.in_org(organization_id)
        applied = _apply_project(
            project_api, project, machine_user_taken=machine_credentials is not None
        )
        project_ids[applied.name] = applied.project_id
        if applied.machine_credentials is not None:
            machine_credentials = applied.machine_credentials
        if organization is None:
            social_idp_ids.extend(applied.social_idp_ids)
        else:
            organization_ids[_organization_provider(organization)] = organization_id
            _apply_organization_policies(
                project_api, organization, applied, artifact.get("tokenClaimAction")
            )

    _grant_machine_user_in_organizations(api, projects, organization_ids)
    _link_social_idps_to_login_policy(api, social_idp_ids)
    _apply_token_claim_action(api, artifact.get("tokenClaimAction"))
    _apply_login_policy(api, artifact.get("loginPolicy"))
    _apply_oidc_settings(api, artifact.get("oidcSettings"))
    _apply_mail_provider(api, artifact.get("mailProvider"))

    logger.info(
        "zitadel_applier_complete projects_applied=%d organizations=%d",
        len(projects),
        len(organization_ids),
    )
    return _Provisioned(project_ids, machine_credentials, organization_ids)


class _Provisioned(NamedTuple):
    """What a provisioning run leaves behind for the files the services read.

    ``project_ids`` maps project name -> assigned id (resolves the plan's audience
    sentinels); ``machine_credentials`` is the inter-service machine credential material
    (``None`` when no project declares a ``machineUser``); ``organization_ids`` maps the
    logical provider name of each provider provisioned into an organization of its own
    to that organization's id.
    """

    project_ids: dict[str, str]
    machine_credentials: dict[str, str] | None
    organization_ids: dict[str, str]


def _require_organization_block(
    project: Mapping[str, object], organization: object
) -> Mapping[str, object]:
    """The project's ``organization`` block, exiting non-zero when it is not an object."""
    if not isinstance(organization, dict):
        logger.error(
            "Project '%s' has a non-object 'organization'. Got: %s. "
            "Fix: regenerate the provisioning artifact.",
            project.get("name"),
            organization,
        )
        sys.exit(1)
    return organization


def _organization_provider(organization: Mapping[str, object]) -> str:
    """The logical provider name an ``organization`` block belongs to.

    Raises:
        SystemExit(1): The block names no provider.
    """
    provider = organization.get("provider")
    if not isinstance(provider, str) or not provider:
        logger.error(
            "Project 'organization' block is missing its 'provider'. Got: %s. "
            "Fix: regenerate the provisioning artifact.",
            organization,
        )
        sys.exit(1)
    return provider


def _apply_organization_policies(
    api: _Api,
    organization: Mapping[str, object],
    applied: "_AppliedProject",
    token_claim_action: object,
) -> None:
    """Converge what is per organization for a provider provisioned into its own one.

    The social IdPs the provider's project declared are listed on the organization's
    login page, the token claim-injection action runs in this organization too (an action
    and its trigger belong to one organization), and the organization's own login policy
    is set, which is where ``forceMfa`` takes effect: the hosted login applies the policy
    of the organization the signing-in user belongs to.

    Args:
        api: Connection context acting in the provider's organization.
        organization: The project's ``organization`` block (``loginPolicy`` optional).
        applied: What converging the project left behind.
        token_claim_action: The artifact's ``tokenClaimAction``, applied here as well.
    """
    _link_social_idps_to_login_policy(api, applied.social_idp_ids)
    _apply_token_claim_action(api, token_claim_action)
    _apply_login_policy(api, organization.get("loginPolicy"), require_custom=True)


def _grant_machine_user_in_organizations(
    api: _Api,
    projects: Sequence[Mapping[str, object]],
    organization_ids: Mapping[str, str],
) -> None:
    """Make the inter-service machine user an ORG_USER_MANAGER of every provider organization.

    The services administer users and write metadata as the machine user, whose home is
    the default organization; a user of a provider's own organization is only reachable
    from there once the machine user is a member of that organization.

    Args:
        api: Connection context acting in the default organization.
        projects: The artifact's projects; the one declaring the ``machineUser`` decides
            whether the grant is wanted.
        organization_ids: Provider name -> organization id of the provider organizations.
    """
    if not organization_ids:
        return
    for project in projects:
        machine_user = project.get("machineUser")
        if not isinstance(machine_user, dict):
            continue
        wants_grant = bool(machine_user.get("grantsMetadataWrite", False)) or bool(
            machine_user.get("grantsUserAdministration", False)
        )
        user_name = machine_user.get("userName")
        if not wants_grant or not isinstance(user_name, str):
            continue
        user_id = _find_machine_user(api, user_name)
        if user_id is None:
            logger.error(
                "The machine user '%s' does not exist after its project was applied. "
                "Fix: re-run the provisioning job.",
                user_name,
            )
            sys.exit(1)
        for organization_id in organization_ids.values():
            _ensure_org_user_manager_grant(api.in_org(organization_id), user_id)


class _AppliedProject(NamedTuple):
    """What converging one project leaves behind: its identifiers, the machine
    credentials it minted (``None`` when it declares no ``machineUser``) and the ids of the
    social IdPs it applied."""

    name: str
    project_id: str
    machine_credentials: dict[str, str] | None
    social_idp_ids: list[str]


def _apply_project(
    api: _Api, project: dict[str, Any], *, machine_user_taken: bool
) -> _AppliedProject:
    """Converge one project: the project, its roles, OIDC apps, machine user
    and social IdPs.

    Args:
        api: The Management API client.
        project: The project entry from the artifact.
        machine_user_taken: An earlier project already provisioned the one
            supported machine user.

    Returns:
        The project's name and id, its machine credentials (``None`` when it
        declares no ``machineUser``) and the ids of its social IdPs.

    Raises:
        SystemExit(1): A second project declares a ``machineUser``.
    """
    _validate_project(project)
    project_name: str = project["name"]
    role_assertion = bool(project.get("projectRoleAssertion", False))

    project_id = _ensure_project(
        api,
        project_name,
        role_assertion,
        bool(project.get("hasProjectCheck", False)),
    )

    introspection_client = project.get("introspectionClient")
    if introspection_client is not None:
        if not isinstance(introspection_client, dict):
            logger.error(
                "Project '%s' has a non-object 'introspectionClient'. Got: %s. "
                "Fix: regenerate the provisioning artifact.",
                project_name,
                introspection_client,
            )
            sys.exit(1)
        _provision_introspection_client(api, project_id, introspection_client)

    roles: list[dict[str, Any]] = project.get("roles", [])
    if roles:
        logger.info(
            "applying_roles project=%s count=%d", project_name, len(roles)
        )
        _ensure_roles(api, project_id, roles)

    oidc_apps: list[dict[str, Any]] = project.get("oidcApps", [])
    if oidc_apps:
        logger.info(
            "applying_oidc_apps project=%s count=%d", project_name, len(oidc_apps)
        )
        _ensure_oidc_apps(api, project_id, oidc_apps)

    machine_credentials = _provision_machine_user(api, project, project_id)
    if machine_credentials is not None and machine_user_taken:
        logger.error(
            "More than one project declares a machineUser (second: '%s'). "
            "Exactly one machine-audience identity provider is supported. "
            "Fix: declare a single machine-audience identity provider.",
            project_name,
        )
        sys.exit(1)

    identity_providers: list[dict[str, Any]] = project.get("identityProviders", [])
    social_idp_ids: list[str] = []
    if identity_providers:
        logger.info(
            "applying_identity_providers project=%s count=%d",
            project_name,
            len(identity_providers),
        )
        social_idp_ids = _ensure_social_idps(api, identity_providers)
    return _AppliedProject(project_name, project_id, machine_credentials, social_idp_ids)


def _apply_token_claim_action(api: _Api, token_claim_action: object) -> None:
    """Converge the Complement-Token claim-injection action.

    Zitadel's default JWT access token carries no profile claims (email/name),
    so without this action every human token is rejected by the gateway's
    required-identity-field check. Org-level and independent of projects, so
    it is applied once after all projects.  Absent only when no provider
    declares a profile-sourceable field.

    Raises:
        SystemExit(1): The artifact's ``tokenClaimAction`` is not an object.
    """
    if token_claim_action is None:
        logger.info("token_claim_action_skipped reason=no_profile_sourced_claims")
        return
    if not isinstance(token_claim_action, dict):
        logger.error(
            "Provisioning artifact 'tokenClaimAction' must be an object. Got: %s. "
            "Fix: regenerate the provisioning artifact.",
            token_claim_action,
        )
        sys.exit(1)
    logger.info("applying_token_claim_action name=%s", token_claim_action.get("name"))
    _ensure_token_claim_action(api, token_claim_action)


def main() -> None:
    """Entry point: configure logging, read env vars + PAT file, and apply."""
    logging.basicConfig(level=logging.INFO, format=_LOG_FORMAT, stream=sys.stdout)

    instance_url = _require_env("ZITADEL_INSTANCE_URL")
    host_header = _require_env("ZITADEL_HOST_HEADER")
    pat_file = _require_env("ZITADEL_PAT_FILE")
    plan_template_file = _require_env("IDENTITY_PROVIDER_PLAN_TEMPLATE_FILE")
    plan_file = _require_env("IDENTITY_PROVIDER_PLAN_FILE")
    provisioning_path = os.environ.get(
        "ZITADEL_PROVISIONING_PATH", DEFAULT_PROVISIONING_PATH
    ).strip()
    if not provisioning_path:
        provisioning_path = DEFAULT_PROVISIONING_PATH

    token = _read_pat(pat_file)

    provisioned = apply_provisioning(
        instance_url=instance_url,
        host_header=host_header,
        token=token,
        provisioning_path=provisioning_path,
    )
    project_ids = provisioned.project_ids
    machine_credentials = provisioned.machine_credentials

    # Render the deployed provider plan with its Zitadel allowedAudiences resolved
    # to the project IDs Zitadel just assigned, so backend services validate the
    # audience the issued access tokens actually carry.
    _render_provider_plan(plan_template_file, plan_file, project_ids)

    # Write the inter-service machine credentials (clientId/clientSecret/audience/
    # tokenUrl/hostHeader) onto the shared volume backend services read to acquire
    # their machine access tokens.  The token endpoint and Host header are
    # static for the deployment target and are recorded here alongside the
    # provisioning-time-minted client credentials so the service needs no env vars
    # to perform the OAuth2 client_credentials exchange.
    machine_credentials_file = os.environ.get(
        "IDENTITY_MACHINE_CREDENTIALS_FILE", ""
    ).strip()
    if machine_credentials is not None and machine_credentials_file:
        machine_credentials["tokenUrl"] = instance_url.rstrip("/") + "/oauth/v2/token"
        machine_credentials["hostHeader"] = host_header
        # The runtime metadata client (a separate task)
        # needs the instance base URL to reach /management/v1; recording it
        # here means no new env var is required on the backend service.
        machine_credentials["instanceOrigin"] = instance_url.rstrip("/")
        # The organization each provider provisioned into an organization of its own lives
        # in: a Management API call about one of its users must name that organization
        # (``x-zitadel-orgid``), because the machine user's own organization is another.
        credentials_document: dict[str, object] = dict(machine_credentials)
        if provisioned.organization_ids:
            credentials_document["organizations"] = provisioned.organization_ids
        _write_machine_credentials(machine_credentials_file, credentials_document)
        _require_machine_audience_accepted(plan_file, machine_credentials_file)
    elif machine_credentials_file:
        logger.info("machine_credentials_skipped reason=no_machine_user_in_artifact")


if __name__ == "__main__":
    main()

